import { GoogleGenAI, Type } from "@google/genai";

const apiKey = process.env.API_KEY;

// 定义单个词语分析的属性
const itemSchemaProperties = {
  word: { type: Type.STRING },
  pinyin: { type: Type.STRING },
  hasDefinitionQuestion: { type: Type.BOOLEAN },
  targetChar: { type: Type.STRING, nullable: true },
  options: { type: Type.ARRAY, items: { type: Type.STRING }, nullable: true },
  correctIndex: { type: Type.INTEGER, nullable: true },
  hasMatchQuestion: { type: Type.BOOLEAN },
  matchOptions: { type: Type.ARRAY, items: { type: Type.STRING }, nullable: true },
  matchCorrectIndex: { type: Type.INTEGER, nullable: true }
};

// 批量分析 Schema (数组)
const batchAnalysisSchema = {
  type: Type.OBJECT,
  properties: {
    results: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: itemSchemaProperties,
        required: ["word", "pinyin"]
      }
    }
  },
  required: ["results"]
};

const poemSchema = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    dynasty: { type: Type.STRING },
    author: { type: Type.STRING },
    content: { type: Type.STRING },
    lines: { type: Type.ARRAY, items: { type: Type.STRING } },
    fillQuestions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          lineIndex: { type: Type.INTEGER },
          pre: { type: Type.STRING },
          answer: { type: Type.STRING },
          post: { type: Type.STRING },
        }
      }
    },
    definitionQuestions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          lineIndex: { type: Type.INTEGER },
          targetChar: { type: Type.STRING },
          options: { type: Type.ARRAY, items: { type: Type.STRING } },
          correctIndex: { type: Type.INTEGER },
        }
      }
    }
  },
  required: ["title", "author", "lines"]
};

const ocrSchema = {
  type: Type.OBJECT,
  properties: {
    words: { type: Type.ARRAY, items: { type: Type.STRING } }
  }
};

const cleanJson = (text) => {
  if (!text) return '{}';
  let cleaned = text.trim();
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    return cleaned.substring(firstBrace, lastBrace + 1);
  }
  return cleaned;
};

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Credentials', true);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS,PATCH,DELETE,POST,PUT');
  res.setHeader('Access-Control-Allow-Headers', 'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version');

  if (req.method === 'OPTIONS') return res.status(200).end();
  if (req.method !== 'POST') return res.status(405).json({ error: 'Method Not Allowed' });
  if (!apiKey) return res.status(500).json({ error: "Server API Key missing." });

  try {
    const ai = new GoogleGenAI({ apiKey });
    const { type, text, words, image } = req.body;

    let model = 'gemini-2.5-flash';
    let parts = [];
    let schema = null;

    if (type === 'batch-words') {
      parts = [{ text: `Analyze the following Chinese words/idioms: ${words.join(', ')}. For each word, provide pinyin, a definition multiple choice question, and a character usage match question. Return an array of results.` }];
      schema = batchAnalysisSchema;
    } else if (type === 'poem') {
      parts = [{ text: `Analyze poem "${text}". JSON output: title, author, fill questions, definition questions.` }];
      schema = poemSchema;
    } else if (type === 'ocr') {
      parts = [
        { inlineData: { mimeType: 'image/jpeg', data: image } },
        { text: "Extract and list only the Chinese words or idioms from this worksheet. Ignore single non-content characters." }
      ];
      schema = ocrSchema;
    } else {
      return res.status(400).json({ error: "Invalid request type" });
    }

    const response = await ai.models.generateContent({
      model: model,
      contents: { parts },
      config: {
        responseMimeType: 'application/json',
        responseSchema: schema,
      }
    });

    const cleanText = cleanJson(response.text);
    const jsonResponse = JSON.parse(cleanText);

    return res.status(200).json(jsonResponse);

  } catch (error) {
    console.error("Backend API Error:", error);
    return res.status(500).json({ error: error.message || "Internal Server Error" });
  }
}

import { AnalysisResult, EntryType } from "../types";

const analyzeWithGeminiBackend = async (payload: any) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60000); 

  try {
    const response = await fetch('/api/analyze', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (!response.ok) {
      throw new Error(`API failure: ${response.status}`);
    }

    return await response.json();
  } catch (error: any) {
    clearTimeout(timeoutId);
    throw error;
  }
};

export const analyzeWordsBatch = async (words: string[]): Promise<AnalysisResult[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'batch-words', words });
    if (data.results && Array.isArray(data.results)) {
      return data.results.map((item: any) => mapDataToResult(item));
    }
    return [];
  } catch (error) {
    console.error("Batch Analysis Error:", error);
    throw error;
  }
};

// Keep single for compatibility or poems
export const analyzeWord = async (word: string): Promise<AnalysisResult> => {
  const res = await analyzeWordsBatch([word]);
  return res[0];
};

export const analyzePoem = async (input: string): Promise<AnalysisResult | null> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'poem', text: input });
    return {
      type: EntryType.POEM,
      word: data.title,
      pinyin: data.author,
      definitionData: null,
      definitionMatchData: null,
      poemData: {
        title: data.title,
        dynasty: data.dynasty,
        author: data.author,
        content: data.content,
        lines: data.lines || [],
        fillAnswers: data.fillQuestions || [],
        definitionQuestions: data.definitionQuestions || []
      }
    };
  } catch (error) {
    return null;
  }
};

export const extractWordsFromImage = async (base64Data: string, mimeType: string): Promise<string[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'ocr', image: base64Data });
    return data.words || [];
  } catch (error) {
    return [];
  }
};

function mapDataToResult(data: any): AnalysisResult {
  return {
    type: EntryType.WORD,
    word: data.word,
    pinyin: data.pinyin,
    definitionData: data.hasDefinitionQuestion && data.options && data.options.length === 4 ? {
      targetChar: data.targetChar || data.word?.[0] || '?',
      options: data.options,
      correctIndex: typeof data.correctIndex === 'number' ? data.correctIndex : 0,
    } : null,
    definitionMatchData: data.hasMatchQuestion && data.matchOptions && data.matchOptions.length === 4 ? {
      targetChar: data.targetChar || data.word?.[0] || '?',
      options: data.matchOptions,
      correctIndex: typeof data.matchCorrectIndex === 'number' ? data.matchCorrectIndex : 0,
    } : null
  };
}

import React, { useState, useRef } from 'react';
import { Loader2, CheckCircle, AlertCircle, Camera, Image as ImageIcon, X, ScrollText, Type } from 'lucide-react';
import { analyzeWordsBatch, extractWordsFromImage, analyzePoem } from '../services/geminiService';
import { WordEntry, QuestionType, AnalysisResult, EntryType, TestStatus } from '../types';

interface WordEntryFormProps {
  onAddWord: (entry: WordEntry) => void;
}

interface DraftEntry {
  id: string;
  word: string;
  analysis: AnalysisResult | null;
  enabledTypes: QuestionType[];
  status: 'pending' | 'analyzing' | 'done' | 'error';
  type: EntryType;
}

const WordEntryForm: React.FC<WordEntryFormProps> = ({ onAddWord }) => {
  const [activeTab, setActiveTab] = useState<EntryType>(EntryType.WORD);
  const [inputText, setInputText] = useState('');
  const [defaultTypes, setDefaultTypes] = useState<QuestionType[]>([QuestionType.PINYIN, QuestionType.DICTATION]);
  const [poemInput, setPoemInput] = useState('');
  const [showCameraModal, setShowCameraModal] = useState(false);
  const [cameraStream, setCameraStream] = useState<MediaStream | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState<string>('');
  const [drafts, setDrafts] = useState<DraftEntry[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const getUniqueWords = (text: string) => {
    return Array.from(new Set(
      text.split(/[ \n,，、;；]+/).map(w => w.trim()).filter(w => w.length > 0)
    ));
  };

  const handleAnalyzeWords = async () => {
    const words = getUniqueWords(inputText);
    if (words.length === 0) return;

    setIsProcessing(true);
    setProcessingStatus('正在初始化队列...');

    const initialDrafts: DraftEntry[] = words.map(w => ({
      id: crypto.randomUUID(),
      word: w,
      analysis: null,
      enabledTypes: [...defaultTypes],
      status: 'pending',
      type: EntryType.WORD
    }));

    setDrafts(initialDrafts);
    setInputText('');

    // 分块处理：每 10 个词一组发送一个请求
    const CHUNK_SIZE = 10;
    const wordChunks = [];
    for (let i = 0; i < words.length; i += CHUNK_SIZE) {
      wordChunks.push(words.slice(i, i + CHUNK_SIZE));
    }

    let processedCount = 0;

    for (const chunk of wordChunks) {
      // 更新状态为正在分析
      setDrafts(prev => prev.map(d => chunk.includes(d.word) ? { ...d, status: 'analyzing' } : d));
      setProcessingStatus(`正在分析... (${processedCount}/${words.length})`);

      try {
        const batchResults = await analyzeWordsBatch(chunk);

        setDrafts(prev => prev.map(d => {
          const result = batchResults.find(r => r.word === d.word);
          if (!result) return d;

          let types = [...d.enabledTypes];
          if (types.includes(QuestionType.DEFINITION) && !result.definitionData) {
            types = types.filter(t => t !== QuestionType.DEFINITION);
          }
          if (types.includes(QuestionType.DEFINITION_MATCH) && !result.definitionMatchData) {
            types = types.filter(t => t !== QuestionType.DEFINITION_MATCH);
          }

          return { ...d, analysis: result, enabledTypes: types, status: 'done' };
        }));
      } catch (e) {
        setDrafts(prev => prev.map(d => chunk.includes(d.word) ? { ...d, status: 'error' } : d));
      }

      processedCount += chunk.length;
    }

    setProcessingStatus('');
    setIsProcessing(false);
  };

  const handleAnalyzePoem = async () => {
    if (!poemInput.trim()) return;
    setIsProcessing(true);
    setProcessingStatus('正在分析古诗词...');
    try {
       const res = await analyzePoem(poemInput);
       if (res) {
         setDrafts([{
           id: crypto.randomUUID(),
           word: res.word,
           analysis: res,
           enabledTypes: [QuestionType.POEM_FILL, QuestionType.POEM_DEFINITION],
           status: 'done',
           type: EntryType.POEM
         }]);
         setPoemInput('');
       }
    } catch (err) {
      setProcessingStatus('分析出错');
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const processBase64Image = async (base64: string, mimeType: string) => {
    setIsProcessing(true);
    setProcessingStatus('正在识别图片...');
    try {
      const extractedWords = await extractWordsFromImage(base64, mimeType);
      if (extractedWords.length > 0) {
        setInputText(prev => prev ? `${prev} ${extractedWords.join(' ')}` : extractedWords.join(' '));
      }
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      processBase64Image(base64String, file.type);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleSaveAll = () => {
    const validDrafts = drafts.filter(d => d.status === 'done' && d.analysis);
    validDrafts.forEach(draft => {
      if (!draft.analysis) return;
      onAddWord({
        id: draft.id,
        type: draft.type,
        word: draft.word,
        pinyin: draft.analysis.pinyin,
        createdAt: Date.now(),
        definitionData: draft.analysis.definitionData || undefined,
        definitionMatchData: draft.analysis.definitionMatchData || undefined,
        poemData: draft.analysis.poemData,
        enabledTypes: draft.enabledTypes,
        testStatus: TestStatus.UNTESTED,
        passedAfterRetries: false
      });
    });
    setDrafts([]);
  };

  const toggleEditType = (draftId: string, type: QuestionType) => {
    setDrafts(prev => prev.map(d => {
      if (d.id !== draftId) return d;
      const types = d.enabledTypes.includes(type)
        ? d.enabledTypes.filter(t => t !== type)
        : [...d.enabledTypes, type];
      return { ...d, enabledTypes: types };
    }));
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 mb-6">
      <div className="flex items-center gap-4 mb-6 border-b border-gray-100 pb-2">
        <button onClick={() => setActiveTab(EntryType.WORD)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.WORD ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <Type className="w-4 h-4" /> 生字词录入
        </button>
        <button onClick={() => setActiveTab(EntryType.POEM)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.POEM ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <ScrollText className="w-4 h-4" /> 古诗词录入
        </button>
      </div>

      {activeTab === EntryType.WORD ? (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="relative mb-4">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="输入多个字词，用空格或逗号分隔。"
              className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[100px] resize-y"
            />
            <div className="absolute bottom-3 right-3 flex gap-2">
              <button onClick={() => fileInputRef.current?.click()} className="p-2 bg-gray-100 hover:bg-gray-200 rounded-full text-gray-600 transition-colors"><ImageIcon className="w-5 h-5" /></button>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
              <button onClick={() => setShowCameraModal(true)} className="p-2 bg-gray-100 hover:bg-gray-200 rounded-full text-gray-600 transition-colors"><Camera className="w-5 h-5" /></button>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-4 mb-4">
            <span className="text-sm text-gray-600 font-medium">默认考点:</span>
            {[QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH].map(t => (
               <label key={t} className="flex items-center space-x-2 cursor-pointer select-none">
                 <input type="checkbox" checked={defaultTypes.includes(t)} onChange={() => setDefaultTypes(prev => prev.includes(t) ? prev.filter(x => x !== t) : [...prev, t])} className="w-4 h-4 text-primary rounded border-gray-300" />
                 <span className="text-sm text-gray-700">{{ [QuestionType.PINYIN]: '注音', [QuestionType.DICTATION]: '书写', [QuestionType.DEFINITION]: '释义', [QuestionType.DEFINITION_MATCH]: '辨析' }[t]}</span>
               </label>
            ))}
          </div>
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">
               {processingStatus && <span className="flex items-center text-primary"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}
             </div>
             <button onClick={handleAnalyzeWords} disabled={isProcessing || !inputText.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-medium transition-colors disabled:opacity-50">开始分析</button>
          </div>
        </div>
      ) : (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <textarea value={poemInput} onChange={(e) => setPoemInput(e.target.value)} placeholder="输入诗名或全诗内容。" className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[120px]" />
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">{processingStatus && <span className="flex items-center text-primary"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}</div>
             <button onClick={handleAnalyzePoem} disabled={isProcessing || !poemInput.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-medium transition-colors disabled:opacity-50">分析古诗</button>
          </div>
        </div>
      )}

      {drafts.length > 0 && (
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-md font-semibold text-gray-700">识别结果 ({drafts.length})</h3>
            <button onClick={handleSaveAll} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center shadow-sm"><CheckCircle className="w-4 h-4 mr-2" /> 确认添加全部</button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {drafts.map((draft) => (
              <div key={draft.id} className="bg-gray-50 rounded-lg p-4 border border-gray-200 relative group">
                <button onClick={() => setDrafts(prev => prev.filter(d => d.id !== draft.id))} className="absolute top-2 right-2 text-gray-400 hover:text-red-500"><X className="w-4 h-4" /></button>
                <div className="flex flex-col gap-1">
                  <h4 className="font-bold text-gray-900">{draft.word} <span className="text-primary text-sm font-normal ml-2">{draft.analysis?.pinyin}</span></h4>
                  <div className="flex flex-wrap gap-1 mt-2">
                    {draft.status === 'done' ? (
                      <>
                        {draft.type === EntryType.WORD ? (
                          <>
                            {['注音', '书写', '释义', '辨析'].map((label, idx) => {
                              const type = [QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH][idx];
                              const isAvailable = idx < 2 || (idx === 2 && draft.analysis?.definitionData) || (idx === 3 && draft.analysis?.definitionMatchData);
                              if (!isAvailable) return null;
                              return <button key={type} onClick={() => toggleEditType(draft.id, type)} className={`px-2 py-0.5 text-[10px] rounded border ${draft.enabledTypes.includes(type) ? 'bg-blue-100 border-blue-200 text-blue-700' : 'bg-white border-gray-200 text-gray-500'}`}>{label}</button>
                            })}
                          </>
                        ) : (
                          <>
                            <span className="text-[10px] text-gray-500">古诗分析完成</span>
                          </>
                        )}
                      </>
                    ) : (
                      <span className="text-xs flex items-center text-gray-400">
                        {draft.status === 'analyzing' && <><Loader2 className="w-3 h-3 mr-1 animate-spin" /> 分析中...</>}
                        {draft.status === 'pending' && '等待中'}
                        {draft.status === 'error' && <><AlertCircle className="w-3 h-3 mr-1 text-red-500" /> 分析失败</>}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

