      // 关键改进：在批次之间引入 1.5 秒延迟，防止触发 API 速率限制
      if (processedCount < words.length) {
        await delay(1500);
      }
    }

    setProcessingStatus('');
    setIsProcessing(false);
  };

  const handleAnalyzePoem = async () => {
    if (!poemInput.trim()) return;
    setIsProcessing(true);
    setProcessingStatus('正在分析古诗词...');
    try {
       const res = await analyzePoem(poemInput);
       if (res) {
         setDrafts([{
           id: crypto.randomUUID(),
           word: res.word,
           analysis: res,
           enabledTypes: [QuestionType.POEM_FILL, QuestionType.POEM_DEFINITION],
           status: 'done',
           type: EntryType.POEM
         }]);
         setPoemInput('');
       }
    } catch (err) {
      setProcessingStatus('分析出错');
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const processBase64Image = async (base64: string, mimeType: string) => {
    setIsProcessing(true);
    setProcessingStatus('正在识别图片...');
    try {
      const extractedWords = await extractWordsFromImage(base64, mimeType);
      if (extractedWords.length > 0) {
        setInputText(prev => prev ? `${prev} ${extractedWords.join(' ')}` : extractedWords.join(' '));
      }
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      processBase64Image(base64String, file.type);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleSaveAll = () => {
    const validDrafts = drafts.filter(d => d.status === 'done' && d.analysis);
    validDrafts.forEach(draft => {
      if (!draft.analysis) return;
      onAddWord({
        id: draft.id,
        type: draft.type,
        word: draft.word,
        pinyin: draft.analysis.pinyin,
        createdAt: Date.now(),
        definitionData: draft.analysis.definitionData || undefined,
        definitionMatchData: draft.analysis.definitionMatchData || undefined,
        poemData: draft.analysis.poemData,
        enabledTypes: draft.enabledTypes,
        testStatus: TestStatus.UNTESTED,
        passedAfterRetries: false
      });
    });
    setDrafts([]);
  };

  const toggleEditType = (draftId: string, type: QuestionType) => {
    setDrafts(prev => prev.map(d => {
      if (d.id !== draftId) return d;
      const types = d.enabledTypes.includes(type)
        ? d.enabledTypes.filter(t => t !== type)
        : [...d.enabledTypes, type];
      return { ...d, enabledTypes: types };
    }));
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 mb-6">
      <div className="flex items-center gap-4 mb-6 border-b border-gray-100 pb-2">
        <button onClick={() => setActiveTab(EntryType.WORD)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.WORD ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <Type className="w-4 h-4" /> 生字词录入
        </button>
        <button onClick={() => setActiveTab(EntryType.POEM)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.POEM ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <ScrollText className="w-4 h-4" /> 古诗词录入
        </button>
      </div>

      {activeTab === EntryType.WORD ? (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="relative mb-4">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="输入多个字词，用空格或逗号分隔。"
              className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[100px] resize-y"
            />
            <div className="absolute bottom-3 right-3 flex gap-2">
              <button onClick={() => fileInputRef.current?.click()} className="p-2 bg-gray-100 hover:bg-gray-200 rounded-full text-gray-600 transition-colors"><ImageIcon className="w-5 h-5" /></button>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-4 mb-4">
            <span className="text-sm text-gray-600 font-medium">默认考点:</span>
            {[QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH].map(t => (
               <label key={t} className="flex items-center space-x-2 cursor-pointer select-none">
                 <input type="checkbox" checked={defaultTypes.includes(t)} onChange={() => setDefaultTypes(prev => prev.includes(t) ? prev.filter(x => x !== t) : [...prev, t])} className="w-4 h-4 text-primary rounded border-gray-300" />
                 <span className="text-sm text-gray-700">{{ [QuestionType.PINYIN]: '注音', [QuestionType.DICTATION]: '书写', [QuestionType.DEFINITION]: '释义', [QuestionType.DEFINITION_MATCH]: '辨析' }[t]}</span>
               </label>
            ))}
          </div>
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">
               {processingStatus && <span className="flex items-center text-primary"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}
             </div>
             <button onClick={handleAnalyzeWords} disabled={isProcessing || !inputText.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-medium transition-colors disabled:opacity-50">开始分析</button>
          </div>
        </div>
      ) : (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <textarea value={poemInput} onChange={(e) => setPoemInput(e.target.value)} placeholder="输入诗名或全诗内容。" className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[120px]" />
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">{processingStatus && <span className="flex items-center text-primary"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}</div>
             <button onClick={handleAnalyzePoem} disabled={isProcessing || !poemInput.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-medium transition-colors disabled:opacity-50">分析古诗</button>
          </div>
        </div>
      )}

      {drafts.length > 0 && (
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-md font-semibold text-gray-700">识别结果 ({drafts.length})</h3>
            <button onClick={handleSaveAll} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center shadow-sm"><CheckCircle className="w-4 h-4 mr-2" /> 确认添加全部</button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto pr-2">
            {drafts.map((draft) => (
              <div key={draft.id} className="bg-gray-50 rounded-lg p-4 border border-gray-200 relative group">
                <button onClick={() => setDrafts(prev => prev.filter(d => d.id !== draft.id))} className="absolute top-2 right-2 text-gray-400 hover:text-red-500"><X className="w-4 h-4" /></button>
                <div className="flex flex-col gap-1">
                  <h4 className="font-bold text-gray-900">{draft.word} <span className="text-primary text-sm font-normal ml-2">{draft.analysis?.pinyin}</span></h4>
                  <div className="flex flex-wrap gap-1 mt-2">
                    {draft.status === 'done' ? (
                      <>
                        {draft.type === EntryType.WORD ? (
                          <>
                            {['注音', '书写', '释义', '辨析'].map((label, idx) => {
                              const type = [QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH][idx];
                              const isAvailable = idx < 2 || (idx === 2 && draft.analysis?.definitionData) || (idx === 3 && draft.analysis?.definitionMatchData);
                              if (!isAvailable) return null;
                              return <button key={type} onClick={() => toggleEditType(draft.id, type)} className={`px-2 py-0.5 text-[10px] rounded border ${draft.enabledTypes.includes(type) ? 'bg-blue-100 border-blue-200 text-blue-700' : 'bg-white border-gray-200 text-gray-500'}`}>{label}</button>
                            })}
                          </>
                        ) : (
                          <>
                            <span className="text-[10px] text-gray-500">古诗分析完成</span>
                          </>
                        )}
                      </>
                    ) : (
                      <span className="text-xs flex items-center text-gray-400">
                        {draft.status === 'analyzing' && <><Loader2 className="w-3 h-3 mr-1 animate-spin" /> 分析中...</>}
                        {draft.status === 'pending' && '等待中'}
                        {draft.status === 'error' && <><AlertCircle className="w-3 h-3 mr-1 text-red-500" /> 分析失败</>}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

