          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">{processingStatus && <span className="flex items-center text-primary"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}</div>
             <button onClick={handleAnalyzePoem} disabled={isProcessing || !poemInput.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-medium transition-colors disabled:opacity-50">分析古诗</button>
          </div>
        </div>
      )}

      {drafts.length > 0 && (
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-md font-semibold text-gray-700">识别结果 ({drafts.length})</h3>
            <div className="flex gap-2">
              {hasFailedItems && (
                <button onClick={handleRetryFailed} disabled={isProcessing} className="bg-orange-50 text-orange-600 hover:bg-orange-100 border border-orange-200 px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center disabled:opacity-50"><RefreshCw className={`w-4 h-4 mr-2 ${isProcessing ? 'animate-spin' : ''}`} /> 重试失败项</button>
              )}
              <button onClick={handleSaveAll} disabled={isProcessing} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center shadow-sm disabled:opacity-50"><CheckCircle className="w-4 h-4 mr-2" /> 确认添加全部</button>
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto pr-2">
            {drafts.map((draft) => (
              <div key={draft.id} className={`rounded-lg p-4 border relative group transition-colors ${draft.status === 'error' ? 'bg-red-50 border-red-200' : 'bg-gray-50 border-gray-200'}`}>
                <button onClick={() => setDrafts(prev => prev.filter(d => d.id !== draft.id))} className="absolute top-2 right-2 text-gray-400 hover:text-red-500"><X className="w-4 h-4" /></button>
                <div className="flex flex-col gap-1">
                  <h4 className="font-bold text-gray-900">{draft.word} <span className="text-primary text-sm font-normal ml-2">{draft.analysis?.pinyin}</span></h4>
                  <div className="flex flex-wrap gap-1 mt-2">
                    {draft.status === 'done' ? (
                      <>
                        {draft.type === EntryType.WORD ? (
                          <>
                            {['注音', '书写', '释义', '辨析'].map((label, idx) => {
                              const type = [QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH][idx];
                              const isAvailable = idx < 2 || (idx === 2 && draft.analysis?.definitionData) || (idx === 3 && draft.analysis?.definitionMatchData);
                              if (!isAvailable) return null;
                              return <button key={type} onClick={() => toggleEditType(draft.id, type)} className={`px-2 py-0.5 text-[10px] rounded border ${draft.enabledTypes.includes(type) ? 'bg-blue-100 border-blue-200 text-blue-700' : 'bg-white border-gray-200 text-gray-500'}`}>{label}</button>
                            })}
                          </>
                        ) : (
                          <>
                            <span className="text-[10px] text-gray-500">古诗分析完成</span>
                          </>
                        )}
                      </>
                    ) : (
                      <div className="flex flex-col gap-1">
                        <span className="text-xs flex items-center text-gray-400">
                          {draft.status === 'analyzing' && <><Loader2 className="w-3 h-3 mr-1 animate-spin" /> 分析中...</>}
                          {draft.status === 'pending' && '等待中'}
                          {draft.status === 'error' && <><AlertCircle className="w-3 h-3 mr-1 text-red-500" /> 分析失败</>}
                        </span>
                        {draft.errorMsg && <span className="text-[10px] text-red-400 flex items-center"><Info className="w-2.5 h-2.5 mr-1" /> {draft.errorMsg}</span>}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default WordEntryForm;

import { AnalysisResult, EntryType } from "../types";

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const analyzeWithGeminiBackend = async (payload: any, retries = 3) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60000); 

  try {
    const response = await fetch('/api/analyze', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: controller.signal
    });

    clearTimeout(timeoutId);

    // 针对 429 频率限制进行更长的指数退避重试
    if (response.status === 429 && retries > 0) {
      const waitTime = (4 - retries) * 5000; // 第一次失败等5秒，第二次等10秒...
      console.warn(`Rate limited, retrying in ${waitTime/1000}s...`);
      await delay(waitTime);
      return analyzeWithGeminiBackend(payload, retries - 1);
    }

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `API failure: ${response.status}`);
    }

    return await response.json();
  } catch (error: any) {
    clearTimeout(timeoutId);
    if (retries > 0 && (error.name === 'AbortError' || error.message.includes('timeout') || error.message.includes('500'))) {
      console.warn("Request unstable, retrying...");
      await delay(2000);
      return analyzeWithGeminiBackend(payload, retries - 1);
    }
    throw error;
  }
};

export const analyzeWordsBatch = async (words: string[]): Promise<AnalysisResult[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'batch-words', words });
    if (data.results && Array.isArray(data.results)) {
      return data.results.map((item: any) => mapDataToResult(item));
    }
    return [];
  } catch (error) {
    console.error("Batch Analysis Error:", error);
    throw error;
  }
};

export const analyzeWord = async (word: string): Promise<AnalysisResult> => {
  const res = await analyzeWordsBatch([word]);
  return res[0];
};

export const analyzePoem = async (input: string): Promise<AnalysisResult | null> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'poem', text: input });
    return {
      type: EntryType.POEM,
      word: data.title,
      pinyin: data.author,
      definitionData: null,
      definitionMatchData: null,
      poemData: {
        title: data.title,
        dynasty: data.dynasty,
        author: data.author,
        content: data.content,
        lines: data.lines || [],
        fillAnswers: data.fillQuestions || [],
        definitionQuestions: data.definitionQuestions || []
      }
    };
  } catch (error) {
    return null;
  }
};

export const extractWordsFromImage = async (base64Data: string, mimeType: string): Promise<string[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'ocr', image: base64Data });
    return data.words || [];
  } catch (error) {
    return [];
  }
};

function mapDataToResult(data: any): AnalysisResult {
  return {
    type: EntryType.WORD,
    word: data.word,
    pinyin: data.pinyin,
    definitionData: data.hasDefinitionQuestion && data.options && data.options.length === 4 ? {
      targetChar: data.targetChar || data.word?.[0] || '?',
      options: data.options,
      correctIndex: typeof data.correctIndex === 'number' ? data.correctIndex : 0,
    } : null,
    definitionMatchData: data.hasMatchQuestion && data.matchOptions && data.matchOptions.length === 4 ? {
      targetChar: data.targetChar || data.word?.[0] || '?',
      options: data.matchOptions,
      correctIndex: typeof data.matchCorrectIndex === 'number' ? data.matchCorrectIndex : 0,
    } : null
  };
}

import React, { useState, useRef } from 'react';
import { Loader2, CheckCircle, AlertCircle, Camera, Image as ImageIcon, X, ScrollText, Type, RefreshCw, Info } from 'lucide-react';
import { analyzeWordsBatch, extractWordsFromImage, analyzePoem } from '../services/geminiService';
import { WordEntry, QuestionType, AnalysisResult, EntryType, TestStatus } from '../types';

interface WordEntryFormProps {
  onAddWord: (entry: WordEntry) => void;
}

interface DraftEntry {
  id: string;
  word: string;
  analysis: AnalysisResult | null;
  enabledTypes: QuestionType[];
  status: 'pending' | 'analyzing' | 'done' | 'error';
  errorMsg?: string;
  type: EntryType;
}

const WordEntryForm: React.FC<WordEntryFormProps> = ({ onAddWord }) => {
  const [activeTab, setActiveTab] = useState<EntryType>(EntryType.WORD);
  const [inputText, setInputText] = useState('');
  const [defaultTypes, setDefaultTypes] = useState<QuestionType[]>([QuestionType.PINYIN, QuestionType.DICTATION]);
  const [poemInput, setPoemInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState<string>('');
  const [drafts, setDrafts] = useState<DraftEntry[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const getUniqueWords = (text: string) => {
    return Array.from(new Set(
      text.split(/[ \n,，、;；]+/).map(w => w.trim()).filter(w => w.length > 0)
    ));
  };

  const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

  const performAnalysis = async (wordsToAnalyze: string[]) => {
    if (wordsToAnalyze.length === 0) return;

    setIsProcessing(true);

    // 保持 3 个一组，这是最稳健的体积
    const CHUNK_SIZE = 3;
    const wordChunks = [];
    for (let i = 0; i < wordsToAnalyze.length; i += CHUNK_SIZE) {
      wordChunks.push(wordsToAnalyze.slice(i, i + CHUNK_SIZE));
    }

    let processedCount = 0;

    for (const chunk of wordChunks) {
      // 1. 设置当前批次为分析中
      setDrafts(prev => prev.map(d => chunk.includes(d.word) && d.status !== 'done' ? { ...d, status: 'analyzing', errorMsg: undefined } : d));
      setProcessingStatus(`分析中... (${processedCount}/${wordsToAnalyze.length})`);

      try {
        const batchResults = await analyzeWordsBatch(chunk);

        // 2. 更新结果，并处理“AI漏选”的情况
        setDrafts(prev => prev.map(d => {
          if (!chunk.includes(d.word)) return d; // 非本批次，不动

          const result = batchResults.find(r => r.word === d.word);

          if (result) {
            let types = [...d.enabledTypes];
            if (types.includes(QuestionType.DEFINITION) && !result.definitionData) {
              types = types.filter(t => t !== QuestionType.DEFINITION);
            }
            if (types.includes(QuestionType.DEFINITION_MATCH) && !result.definitionMatchData) {
              types = types.filter(t => t !== QuestionType.DEFINITION_MATCH);
            }
            return { ...d, analysis: result, enabledTypes: types, status: 'done' };
          } else {
            // AI 没返回这个词的结果，标记为错误而非一直处于 analyzing
            return { ...d, status: 'error', errorMsg: 'AI未返回结果，请重试' };
          }
        }));
      } catch (e: any) {
        console.error("Chunk failed:", chunk, e);
        const errorMsg = e.message?.includes('429') ? '服务器繁忙 (Rate Limit)' : '网络异常或分析超时';
        setDrafts(prev => prev.map(d => chunk.includes(d.word) && d.status === 'analyzing' ? { ...d, status: 'error', errorMsg } : d));
      }

      processedCount += chunk.length;
      if (processedCount < wordsToAnalyze.length) {
        setProcessingStatus(`休息中... (${processedCount}/${wordsToAnalyze.length})`);
        await delay(4000);
      }
    }

    setProcessingStatus('');
    setIsProcessing(false);
  };

  const handleAnalyzeWords = async () => {
    const words = getUniqueWords(inputText);
    if (words.length === 0) return;

    const initialDrafts: DraftEntry[] = words.map(w => ({
      id: crypto.randomUUID(),
      word: w,
      analysis: null,
      enabledTypes: [...defaultTypes],
      status: 'pending',
      type: EntryType.WORD
    }));

    setDrafts(initialDrafts);
    setInputText('');
    await performAnalysis(words);
  };

  const handleRetryFailed = async () => {
    const failedWords = drafts.filter(d => d.status === 'error').map(d => d.word);
    if (failedWords.length === 0) return;

    setDrafts(prev => prev.map(d => d.status === 'error' ? { ...d, status: 'pending', errorMsg: undefined } : d));
    await performAnalysis(failedWords);
  };

  const handleAnalyzePoem = async () => {
    if (!poemInput.trim()) return;
    setIsProcessing(true);
    setProcessingStatus('正在分析古诗词...');
    try {
       const res = await analyzePoem(poemInput);
       if (res) {
         setDrafts([{
           id: crypto.randomUUID(),
           word: res.word,
           analysis: res,
           enabledTypes: [QuestionType.POEM_FILL, QuestionType.POEM_DEFINITION],
           status: 'done',
           type: EntryType.POEM
         }]);
         setPoemInput('');
       }
    } catch (err) {
      setProcessingStatus('分析出错');
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const processBase64Image = async (base64: string, mimeType: string) => {
    setIsProcessing(true);
    setProcessingStatus('正在识别图片...');
    try {
      const extractedWords = await extractWordsFromImage(base64, mimeType);
      if (extractedWords.length > 0) {
        setInputText(prev => prev ? `${prev} ${extractedWords.join(' ')}` : extractedWords.join(' '));
      }
    } finally {
      setIsProcessing(false);
      setProcessingStatus('');
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      processBase64Image(base64String, file.type);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleSaveAll = () => {
    const validDrafts = drafts.filter(d => d.status === 'done' && d.analysis);
    validDrafts.forEach(draft => {
      if (!draft.analysis) return;
      onAddWord({
        id: draft.id,
        type: draft.type,
        word: draft.word,
        pinyin: draft.analysis.pinyin,
        createdAt: Date.now(),
        definitionData: draft.analysis.definitionData || undefined,
        definitionMatchData: draft.analysis.definitionMatchData || undefined,
        poemData: draft.analysis.poemData,
        enabledTypes: draft.enabledTypes,
        testStatus: TestStatus.UNTESTED,
        passedAfterRetries: false
      });
    });
    setDrafts([]);
  };

  const toggleEditType = (draftId: string, type: QuestionType) => {
    setDrafts(prev => prev.map(d => {
      if (d.id !== draftId) return d;
      const types = d.enabledTypes.includes(type)
        ? d.enabledTypes.filter(t => t !== type)
        : [...d.enabledTypes, type];
      return { ...d, enabledTypes: types };
    }));
  };

  const hasFailedItems = drafts.some(d => d.status === 'error');
  const finishedItemsCount = drafts.filter(d => d.status === 'done').length;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 mb-6">
      <div className="flex items-center gap-4 mb-6 border-b border-gray-100 pb-2">
        <button onClick={() => setActiveTab(EntryType.WORD)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.WORD ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <Type className="w-4 h-4" /> 生字词录入
        </button>
        <button onClick={() => setActiveTab(EntryType.POEM)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.POEM ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <ScrollText className="w-4 h-4" /> 古诗词录入
        </button>
      </div>

      {activeTab === EntryType.WORD ? (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="relative mb-4">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="输入多个字词，用空格或逗号分隔。"
              className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[100px] resize-y"
            />
            <div className="absolute bottom-3 right-3 flex gap-2">
              <button onClick={() => fileInputRef.current?.click()} className="p-2 bg-gray-100 hover:bg-gray-200 rounded-full text-gray-600 transition-colors"><ImageIcon className="w-5 h-5" /></button>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-4 mb-4">
            <span className="text-sm text-gray-600 font-medium">默认考点:</span>
            {[QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH].map(t => (
               <label key={t} className="flex items-center space-x-2 cursor-pointer select-none">
                 <input type="checkbox" checked={defaultTypes.includes(t)} onChange={() => setDefaultTypes(prev => prev.includes(t) ? prev.filter(x => x !== t) : [...prev, t])} className="w-4 h-4 text-primary rounded border-gray-300" />
                 <span className="text-sm text-gray-700 font-medium">{{ [QuestionType.PINYIN]: '注音', [QuestionType.DICTATION]: '书写', [QuestionType.DEFINITION]: '释义', [QuestionType.DEFINITION_MATCH]: '辨析' }[t]}</span>
               </label>
            ))}
          </div>
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">
               {processingStatus && <span className="flex items-center text-primary font-medium"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}
             </div>
             <button onClick={handleAnalyzeWords} disabled={isProcessing || !inputText.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-bold transition-all transform active:scale-95 disabled:opacity-50 disabled:scale-100">开始分析</button>
          </div>
        </div>
      ) : (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <textarea value={poemInput} onChange={(e) => setPoemInput(e.target.value)} placeholder="输入诗名或全诗内容。" className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[120px]" />
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">{processingStatus && <span className="flex items-center text-primary font-medium"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}</div>
             <button onClick={handleAnalyzePoem} disabled={isProcessing || !poemInput.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-bold transition-all transform active:scale-95 disabled:opacity-50">分析古诗</button>
          </div>
        </div>
      )}

      {drafts.length > 0 && (
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-md font-bold text-gray-800">识别结果 ({finishedItemsCount}/{drafts.length})</h3>
            <div className="flex gap-2">
              {hasFailedItems && (
                <button onClick={handleRetryFailed} disabled={isProcessing} className="bg-orange-50 text-orange-600 hover:bg-orange-100 border border-orange-200 px-4 py-2 rounded-lg text-sm font-bold transition-colors flex items-center disabled:opacity-50"><RefreshCw className={`w-4 h-4 mr-2 ${isProcessing ? 'animate-spin' : ''}`} /> 重试失败项</button>
              )}
              <button onClick={handleSaveAll} disabled={isProcessing || finishedItemsCount === 0} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-bold transition-colors flex items-center shadow-sm disabled:opacity-50"><CheckCircle className="w-4 h-4 mr-2" /> 确认添加全部</button>
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto pr-2">
            {drafts.map((draft) => (
              <div key={draft.id} className={`rounded-lg p-4 border relative group transition-all duration-300 ${draft.status === 'error' ? 'bg-red-50 border-red-200' : draft.status === 'analyzing' ? 'bg-indigo-50 border-indigo-200' : 'bg-gray-50 border-gray-200'}`}>
                <button onClick={() => setDrafts(prev => prev.filter(d => d.id !== draft.id))} className="absolute top-2 right-2 text-gray-400 hover:text-red-500 transition-colors"><X className="w-4 h-4" /></button>
                <div className="flex flex-col gap-1">
                  <h4 className="font-bold text-gray-900 flex items-center gap-2">
                    {draft.word} 
                    {draft.status === 'done' && <span className="text-primary text-sm font-normal">{draft.analysis?.pinyin}</span>}
                    {draft.status === 'done' && <CheckCircle className="w-4 h-4 text-green-500" />}
                  </h4>
                  <div className="flex flex-wrap gap-1 mt-2">
                    {draft.status === 'done' ? (
                      <>
                        {draft.type === EntryType.WORD ? (
                          <>
                            {['注音', '书写', '释义', '辨析'].map((label, idx) => {
                              const type = [QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH][idx];
                              const isAvailable = idx < 2 || (idx === 2 && draft.analysis?.definitionData) || (idx === 3 && draft.analysis?.definitionMatchData);
                              if (!isAvailable) return null;
                              return <button key={type} onClick={() => toggleEditType(draft.id, type)} className={`px-2 py-0.5 text-[10px] font-bold rounded border transition-colors ${draft.enabledTypes.includes(type) ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'}`}>{label}</button>
                            })}
                          </>
                        ) : (
                          <span className="text-[10px] text-gray-500 italic">古诗分析完成</span>
                        )}
                      </>
                    ) : (
                      <div className="flex flex-col gap-1 w-full">
                        <span className="text-xs flex items-center text-gray-500 font-medium">
                          {draft.status === 'analyzing' && <><Loader2 className="w-3 h-3 mr-1.5 animate-spin text-primary" /> 深度分析中...</>}
                          {draft.status === 'pending' && <span className="text-gray-400">队列等待中</span>}
                          {draft.status === 'error' && <><AlertCircle className="w-3 h-3 mr-1.5 text-red-500" /> 分析失败</>}
                        </span>
                        {draft.errorMsg && <span className="text-[10px] text-red-500 bg-red-100/50 px-2 py-0.5 rounded flex items-center"><Info className="w-2.5 h-2.5 mr-1" /> {draft.errorMsg}</span>}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default WordEntryForm;

export enum EntryType {
  WORD = 'WORD',
  POEM = 'POEM'
}

export enum QuestionType {
  PINYIN = 'PINYIN', // Word -> Write Pinyin
  DICTATION = 'DICTATION', // Pinyin -> Write Word
  DEFINITION = 'DEFINITION', // Word -> Select Meaning (Explanation)
  DEFINITION_MATCH = 'DEFINITION_MATCH', // Word -> Select word with same character meaning
  POEM_FILL = 'POEM_FILL', // Poem -> Fill in the blank
  POEM_DEFINITION = 'POEM_DEFINITION' // Poem -> Select Meaning of character
}

export enum TestStatus {
  UNTESTED = 'UNTESTED',
  PASSED = 'PASSED',
  FAILED = 'FAILED'
}

export interface DefinitionQuestionData {
  targetChar: string; // The specific character being tested
  options: string[]; // 4 options (Definitions)
  correctIndex: number; // 0-3
}

export enum MatchMode {
  SAME_AS_TARGET = 'SAME_AS_TARGET', // 模式2：在词群中找意思相同的字 (如图一)
  SYNONYM_CHOICE = 'SYNONYM_CHOICE', // 模式1：近义词填空 (选词填空)
  TWO_WAY_COMPARE = 'TWO_WAY_COMPARE' // 模式3：两个词中的字义判断 (如图二)
}

export interface DefinitionMatchData {
  mode: MatchMode;
  targetChar: string; 
  // SAME_AS_TARGET & SYNONYM_CHOICE use these:
  context?: string; // 语境，如 "日益紧密"
  options?: string[]; // 4个选项
  correctIndex?: number;
  // TWO_WAY_COMPARE uses these:
  compareWordA?: string; // 如 "题西林壁"
  compareWordB?: string; // 如 "小题大做"
  isSame?: boolean; // 意思是否相同
}

export interface PoemData {
  title: string;
  dynasty: string;
  author: string;
  content: string; 
  lines: string[]; 
  fillAnswers: {
    lineIndex: number;
    answer: string; 
    pre: string; 
    post: string; 
  }[];
  definitionQuestions: {
    lineIndex: number;
    targetChar: string;
    options: string[];
    correctIndex: number;
  }[];
}

export interface WordEntry {
  id: string;
  type: EntryType;
  word: string; 
  pinyin: string; 
  createdAt: number;
  definitionData?: DefinitionQuestionData;
  definitionMatchData?: DefinitionMatchData; 
  poemData?: PoemData;
  enabledTypes: QuestionType[]; 
  testStatus: TestStatus;
  passedAfterRetries: boolean;
}

export interface AnalysisResult {
  type: EntryType;
  word: string;
  pinyin: string;
  definitionData: DefinitionQuestionData | null;
  definitionMatchData: DefinitionMatchData | null;
  poemData?: PoemData;
}

import { GoogleGenAI, Type } from "@google/genai";

const apiKey = process.env.API_KEY;

const itemSchemaProperties = {
  word: { type: Type.STRING },
  pinyin: { type: Type.STRING },
  hasDefinitionQuestion: { type: Type.BOOLEAN },
  targetChar: { type: Type.STRING, nullable: true },
  options: { type: Type.ARRAY, items: { type: Type.STRING }, nullable: true },
  correctIndex: { type: Type.INTEGER, nullable: true },
  // 辨析题增强
  hasMatchQuestion: { type: Type.BOOLEAN },
  matchMode: { type: Type.STRING, description: "SAME_AS_TARGET, SYNONYM_CHOICE, or TWO_WAY_COMPARE" },
  matchContext: { type: Type.STRING, nullable: true },
  matchOptions: { type: Type.ARRAY, items: { type: Type.STRING }, nullable: true },
  matchCorrectIndex: { type: Type.INTEGER, nullable: true },
  compareWordA: { type: Type.STRING, nullable: true },
  compareWordB: { type: Type.STRING, nullable: true },
  isSame: { type: Type.BOOLEAN, nullable: true }
};

const batchAnalysisSchema = {
  type: Type.OBJECT,
  properties: {
    results: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: itemSchemaProperties,
        required: ["word", "pinyin", "hasMatchQuestion"]
      }
    }
  },
  required: ["results"]
};

const poemSchema = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    dynasty: { type: Type.STRING },
    author: { type: Type.STRING },
    content: { type: Type.STRING },
    lines: { type: Type.ARRAY, items: { type: Type.STRING } },
    fillQuestions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          lineIndex: { type: Type.INTEGER },
          pre: { type: Type.STRING },
          answer: { type: Type.STRING },
          post: { type: Type.STRING },
        }
      }
    },
    definitionQuestions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          lineIndex: { type: Type.INTEGER },
          targetChar: { type: Type.STRING },
          options: { type: Type.ARRAY, items: { type: Type.STRING } },
          correctIndex: { type: Type.INTEGER },
        }
      }
    }
  },
  required: ["title", "author", "lines"]
};

const ocrSchema = {
  type: Type.OBJECT,
  properties: {
    words: { type: Type.ARRAY, items: { type: Type.STRING } }
  }
};

const cleanJson = (text) => {
  if (!text) return '{}';
  let cleaned = text.trim();
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    return cleaned.substring(firstBrace, lastBrace + 1);
  }
  return cleaned;
};

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Credentials', true);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS,PATCH,DELETE,POST,PUT');
  res.setHeader('Access-Control-Allow-Headers', 'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version');

  if (req.method === 'OPTIONS') return res.status(200).end();
  if (req.method !== 'POST') return res.status(405).json({ error: 'Method Not Allowed' });
  if (!apiKey) return res.status(500).json({ error: "Server API Key missing." });

  try {
    const ai = new GoogleGenAI({ apiKey });
    const { type, text, words, image } = req.body;

    let model = 'gemini-3-flash-preview';
    let parts = [];
    let schema = null;

    if (type === 'batch-words') {
      parts = [{ text: `你是一个资深的语文教育专家。请分析以下词语：${words.join(', ')}。
      要求：
      1. 为每个词提供精准的拼音。
      2. 字义题：提取词中重点单字，生成4个不同定义的选项。
      3. 辨析题（重点）：每个词必须从以下三种模式中【任选一种】最合适的：
         - 模式A(SAME_AS_TARGET)：给出一个语境词（如"日益紧密"），让学生从4个含该字的词中选出字义相同的词。
         - 模式B(SYNONYM_CHOICE)：提供一个含有空格的简短句子，给出该词及其一个近义词（如"日益"和"更加"），让学生选出最合适的。
         - 模式C(TWO_WAY_COMPARE)：给出两个含有相同字的短语（如"题西林壁"和"小题大做"），判断其中该字的意思是否相同。
      输出必须严格符合提供的 JSON Schema 格式。` }];
      schema = batchAnalysisSchema;
    } else if (type === 'poem') {
      parts = [{ text: `分析古诗 "${text}"。输出 JSON 包含标题、作者、全文、填空题和释义题。` }];
      schema = poemSchema;
    } else if (type === 'ocr') {
      parts = [
        { inlineData: { mimeType: 'image/jpeg', data: image } },
        { text: "提取图中的所有中文生词、成语。排除单个无意义字符。" }
      ];
      schema = ocrSchema;
    } else {
      return res.status(400).json({ error: "Invalid request type" });
    }

    const response = await ai.models.generateContent({
      model: model,
      contents: { parts },
      config: {
        responseMimeType: 'application/json',
        responseSchema: schema,
      }
    });

    if (!response.text) {
      throw new Error("AI returned empty response");
    }

    const cleanText = cleanJson(response.text);
    const jsonResponse = JSON.parse(cleanText);

    return res.status(200).json(jsonResponse);

  } catch (error) {
    console.error("Backend API Error:", error);
    const statusCode = error.message?.includes('429') ? 429 : 500;
    return res.status(statusCode).json({ error: error.message || "Internal Server Error" });
  }
}

import { AnalysisResult, EntryType, MatchMode } from "../types";

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const analyzeWithGeminiBackend = async (payload: any, retries = 3) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60000); 

  try {
    const response = await fetch('/api/analyze', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: controller.signal
    });

    clearTimeout(timeoutId);

    if (response.status === 429 && retries > 0) {
      const waitTime = (4 - retries) * 5000; 
      console.warn(`Rate limited, retrying in ${waitTime/1000}s...`);
      await delay(waitTime);
      return analyzeWithGeminiBackend(payload, retries - 1);
    }

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `API failure: ${response.status}`);
    }

    return await response.json();
  } catch (error: any) {
    clearTimeout(timeoutId);
    if (retries > 0 && (error.name === 'AbortError' || error.message.includes('timeout') || error.message.includes('500'))) {
      console.warn("Request unstable, retrying...");
      await delay(2000);
      return analyzeWithGeminiBackend(payload, retries - 1);
    }
    throw error;
  }
};

export const analyzeWordsBatch = async (words: string[]): Promise<AnalysisResult[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'batch-words', words });
    if (data.results && Array.isArray(data.results)) {
      return data.results.map((item: any) => mapDataToResult(item));
    }
    return [];
  } catch (error) {
    console.error("Batch Analysis Error:", error);
    throw error;
  }
};

export const analyzeWord = async (word: string): Promise<AnalysisResult> => {
  const res = await analyzeWordsBatch([word]);
  return res[0];
};

export const analyzePoem = async (input: string): Promise<AnalysisResult | null> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'poem', text: input });
    return {
      type: EntryType.POEM,
      word: data.title,
      pinyin: data.author,
      definitionData: null,
      definitionMatchData: null,
      poemData: {
        title: data.title,
        dynasty: data.dynasty,
        author: data.author,
        content: data.content,
        lines: data.lines || [],
        fillAnswers: data.fillQuestions || [],
        definitionQuestions: data.definitionQuestions || []
      }
    };
  } catch (error) {
    return null;
  }
};

export const extractWordsFromImage = async (base64Data: string, mimeType: string): Promise<string[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'ocr', image: base64Data });
    return data.words || [];
  } catch (error) {
    return [];
  }
};

function mapDataToResult(data: any): AnalysisResult {
  let matchData = null;
  if (data.hasMatchQuestion) {
    matchData = {
      mode: data.matchMode as MatchMode || MatchMode.SAME_AS_TARGET,
      targetChar: data.targetChar || data.word?.[0] || '?',
      context: data.matchContext,
      options: data.matchOptions,
      correctIndex: data.matchCorrectIndex,
      compareWordA: data.compareWordA,
      compareWordB: data.compareWordB,
      isSame: data.isSame
    };
  }

  return {
    type: EntryType.WORD,
    word: data.word,
    pinyin: data.pinyin,
    definitionData: data.hasDefinitionQuestion && data.options && data.options.length === 4 ? {
      targetChar: data.targetChar || data.word?.[0] || '?',
      options: data.options,
      correctIndex: typeof data.correctIndex === 'number' ? data.correctIndex : 0,
    } : null,
    definitionMatchData: matchData
  };
}

