                <h2 className="text-lg font-bold mb-6 font-kai flex items-center border-l-4 border-black pl-3">四、词语释义选择</h2>
                <div className="space-y-6 pl-4">
                  {questions.definition.map((w, idx) => (
                    <div key={idx} className="question-item">
                      <div className="font-serif text-base mb-2 leading-relaxed">
                        {idx + 1}. “<span className="font-bold underline underline-offset-4">{w.word}</span>”中“<span className="font-bold text-lg">{w.definitionData?.targetChar}</span>”的意思是：（ &nbsp; ）
                      </div>
                      <div className="grid grid-cols-2 gap-x-8 gap-y-2 pl-6 text-sm font-kai">
                        {w.definitionData?.options.map((opt, oIdx) => (
                          <div key={oIdx} className="flex"><span className="mr-2 font-bold">{String.fromCharCode(65 + oIdx)}.</span><span>{opt}</span></div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {questions.definitionMatch.length > 0 && (
               <div className="mb-10 break-inside-auto">
               <h2 className="text-lg font-bold mb-6 font-kai flex items-center border-l-4 border-black pl-3">五、字词深度辨析</h2>
               <div className="space-y-8 pl-4">
                 {questions.definitionMatch.map((w, idx) => {
                   const m = w.definitionMatchData!;

                   if (m.mode === MatchMode.TWO_WAY_COMPARE) {
                     return (
                        <div key={idx} className="question-item text-base">
                          <div className="flex items-center justify-between border-2 border-gray-100 rounded-lg p-4">
                            <div className="font-serif">{idx + 1}. 判断“<span className="font-bold">{m.targetChar}</span>”在下列词语中意思是否相同：</div>
                            <div className="flex gap-8 font-serif font-bold text-lg items-center">
                               <span className="border-b-2 border-black px-2">{m.compareWordA}</span> 
                               <span className="text-gray-300">vs</span>
                               <span className="border-b-2 border-black px-2">{m.compareWordB}</span>
                               <span className="ml-4 text-sm text-gray-400 font-sans border border-gray-300 px-2 rounded">（ &nbsp; ）</span>
                            </div>
                          </div>
                        </div>
                     );
                   } else if (m.mode === MatchMode.SYNONYM_CHOICE) {
                     return (
                        <div key={idx} className="question-item space-y-3">
                           <div className="font-serif text-base leading-relaxed">
                              {idx + 1}. 选出最恰当的词语填入括号内：<br/>
                              “<span className="font-sans italic">{m.context || '... ( ) ...'}</span>”
                           </div>
                           <div className="grid grid-cols-2 gap-4 pl-6 text-sm font-kai">
                              {m.options?.slice(0, 4).map((opt, oIdx) => (
                                <div key={oIdx} className="flex"><span className="mr-2 font-bold">{String.fromCharCode(65 + oIdx)}.</span><span>{opt}</span></div>
                              ))}
                           </div>
                        </div>
                     );
                   } else {
                     return (
                        <div key={idx} className="question-item space-y-3">
                          <div className="font-serif text-base leading-relaxed">
                            {idx + 1}. 与“<span className="font-bold underline underline-offset-4">{m.context || w.word}</span>”中“<span className="font-bold text-lg">{m.targetChar}</span>”意思相同的一项是：（ &nbsp; ）
                          </div>
                          <div className="grid grid-cols-2 gap-4 pl-6 text-sm font-kai">
                            {m.options?.slice(0, 4).map((opt, oIdx) => (
                              <div key={oIdx} className="flex"><span className="mr-2 font-bold">{String.fromCharCode(65 + oIdx)}.</span><span>{opt}</span></div>
                            ))}
                          </div>
                        </div>
                     );
                   }
                 })}
               </div>
             </div>
            )}
          </div>

          <div className="print-break-before"></div>

          {/* 答案页 */}
          <div className="bg-white shadow-lg w-[210mm] min-h-[297mm] mx-auto p-[20mm] box-border relative text-black print:shadow-none print:w-full print:m-0">
            <div className="text-center border-b-2 border-black pb-4 mb-10">
              <h1 className="text-xl font-bold font-serif tracking-widest">参考答案与解析</h1>
            </div>

            <div className="space-y-10">
                <div className="grid grid-cols-2 gap-12 print:flex print:flex-wrap">
                  {questions.pinyin.length > 0 && (
                    <div className="border-t pt-4 print:w-1/2">
                      <h3 className="font-bold text-base mb-4 bg-gray-50 p-2">1. 看汉字写拼音</h3>
                      <div className="space-y-2 text-sm">{questions.pinyin.map((w, i) => (<div key={i} className="flex justify-between border-b border-dashed"><span>{w.word}</span><span className="font-bold text-primary">{w.pinyin}</span></div>))}</div>
                    </div>
                  )}
                  {questions.dictation.length > 0 && (
                    <div className="border-t pt-4 print:w-1/2">
                      <h3 className="font-bold text-base mb-4 bg-gray-50 p-2">2. 看拼音写词语</h3>
                      <div className="space-y-2 text-sm">{questions.dictation.map((w, i) => (<div key={i} className="flex justify-between border-b border-dashed"><span>{w.pinyin}</span><span className="font-bold text-primary">{w.word}</span></div>))}</div>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-12 print:flex print:flex-wrap">
                    {questions.definition.length > 0 && (
                      <div className="border-t pt-4 print:w-1/2">
                        <h3 className="font-bold text-base mb-4 bg-gray-50 p-2">4. 词语释义答案</h3>
                        <div className="grid grid-cols-4 gap-4 text-sm font-bold">
                          {questions.definition.map((w, i) => (<div key={i}>{i+1}. {String.fromCharCode(65 + (w.definitionData?.correctIndex || 0))}</div>))}
                        </div>
                      </div>
                    )}
                    {questions.definitionMatch.length > 0 && (
                      <div className="border-t pt-4 print:w-1/2">
                        <h3 className="font-bold text-base mb-4 bg-gray-50 p-2">5. 字词辨析答案</h3>
                        <div className="grid grid-cols-4 gap-4 text-sm font-bold">
                          {questions.definitionMatch.map((w, i) => {
                            const m = w.definitionMatchData!;
                            const ans = m.mode === MatchMode.TWO_WAY_COMPARE ? (m.isSame ? '相同' : '不同') : String.fromCharCode(65 + (m.correctIndex || 0));
                            return <div key={i}>{i+1}. {ans}</div>;
                          })}
                        </div>
                      </div>
                    )}
                </div>

                {questions.poemFill.length > 0 && (
                  <div className="border-t pt-4">
                    <h3 className="font-bold text-base mb-4 bg-gray-50 p-2">3. 古诗默写答案</h3>
                    <div className="space-y-4 text-sm">
                      {questions.poemFill.map((w, i) => (
                        <div key={i} className="flex gap-4">
                          <span className="font-bold shrink-0">《{w.word}》</span>
                          <span className="font-serif">{(w.poemData?.fillAnswers as any[] || []).map(f => f.answer).join(' / ')}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ExamGenerator;

import React, { useState, useRef } from 'react';
import { Loader2, CheckCircle, AlertCircle, Camera, Image as ImageIcon, X, ScrollText, Type, RefreshCw, Info } from 'lucide-react';
import { analyzeWordsBatch, extractWordsFromImage, analyzePoem } from '../services/geminiService';
import { WordEntry, QuestionType, AnalysisResult, EntryType, TestStatus } from '../types';

interface DraftEntry {
  id: string;
  word: string;
  analysis: AnalysisResult | null;
  enabledTypes: QuestionType[];
  status: 'pending' | 'analyzing' | 'done' | 'error';
  errorMsg?: string;
  type: EntryType;
}

interface WordEntryFormProps {
  onAddWord: (entry: WordEntry) => void;
}

const WordEntryForm: React.FC<WordEntryFormProps> = ({ onAddWord }) => {
  const [activeTab, setActiveTab] = useState<EntryType>(EntryType.WORD);
  const [inputText, setInputText] = useState('');
  // 修改：默认不勾选任何考点，强迫用户手动选择
  const [defaultTypes, setDefaultTypes] = useState<QuestionType[]>([]);
  const [poemInput, setPoemInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState<string>('');
  const [drafts, setDrafts] = useState<DraftEntry[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const getUniqueWords = (text: string) => {
    const normalized = text.replace(/\s+(vs|VS)\s+/g, ' vs ')
                           .replace(/([^\s])(\/|\|)([^\s])/g, '$1 / $3');
    const lines = normalized.split(/[\n,，、;；]+/).map(w => w.trim()).filter(w => w.length > 0);
    const results: string[] = [];
    lines.forEach(line => {
      if (line.toLowerCase().includes(' vs ') || line.includes('/') || line.includes('和')) {
        results.push(line);
      } else {
        const parts = line.split(/\s+/).filter(p => p.length > 0);
        results.push(...parts);
      }
    });
    return Array.from(new Set(results));
  };

  const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

  const performAnalysis = async (wordsToAnalyze: string[]) => {
    if (wordsToAnalyze.length === 0) return;
    setIsProcessing(true);
    let processedCount = 0;

    for (const word of wordsToAnalyze) {
      setDrafts(prev => prev.map(d => d.word === word && d.status !== 'done' ? { ...d, status: 'analyzing', errorMsg: undefined } : d));
      setProcessingStatus(`正在深度分析: ${word} (${processedCount + 1}/${wordsToAnalyze.length})`);

      try {
        const batchResults = await analyzeWordsBatch([word]);
        const result = batchResults[0];

        if (result) {
          setDrafts(prev => prev.map(d => {
            if (d.word !== word) return d;
            return { ...d, analysis: result, status: 'done' };
          }));
        } else {
          setDrafts(prev => prev.map(d => d.word === word ? { ...d, status: 'error', errorMsg: 'AI解析超时' } : d));
        }
      } catch (e: any) {
        const isRateLimit = e.message?.includes('429') || e.message?.toLowerCase().includes('too many requests');
        const errorMsg = isRateLimit ? '服务器忙(请稍后重试)' : '接口异常';
        setDrafts(prev => prev.map(d => d.word === word ? { ...d, status: 'error', errorMsg } : d));
        if (isRateLimit) {
           setProcessingStatus(`触发频率限制，已停止后续请求`);
           break;
        }
      }
      processedCount++;
      if (processedCount < wordsToAnalyze.length) {
        setProcessingStatus(`AI 正在休息... (${processedCount}/${wordsToAnalyze.length})`);
        await delay(5000); 
      }
    }
    setIsProcessing(false);
  };

  const handleAnalyzeWords = async () => {
    // 新增：校验是否选择了考点
    if (defaultTypes.length === 0) {
      alert("请至少选择一个默认考点（如：注音、书写等）后再开始分析。");
      return;
    }

    const words = getUniqueWords(inputText);
    if (words.length === 0) return;
    const initialDrafts: DraftEntry[] = words.map(w => ({
      id: crypto.randomUUID(),
      word: w,
      analysis: null,
      enabledTypes: [...defaultTypes],
      status: 'pending',
      type: EntryType.WORD
    }));
    setDrafts(initialDrafts);
    setInputText('');
    await performAnalysis(words);
  };

  const handleRetryFailed = async () => {
    const failedItems = drafts.filter(d => d.status === 'error');
    if (failedItems.length === 0) return;
    const failedWords = failedItems.map(d => d.word);
    setDrafts(prev => prev.map(d => d.status === 'error' ? { ...d, status: 'pending', errorMsg: undefined } : d));
    await performAnalysis(failedWords);
  };

  const handleSaveAll = () => {
    const validDrafts = drafts.filter(d => d.status === 'done' && d.analysis);
    validDrafts.forEach(draft => {
      if (!draft.analysis) return;
      onAddWord({
        id: draft.id,
        type: draft.type,
        word: draft.word,
        pinyin: draft.analysis.pinyin,
        createdAt: Date.now(),
        definitionData: draft.analysis.definitionData || undefined,
        definitionMatchData: draft.analysis.definitionMatchData || undefined,
        poemData: draft.analysis.poemData,
        enabledTypes: draft.enabledTypes,
        testStatus: TestStatus.UNTESTED,
        passedAfterRetries: false
      });
    });
    setDrafts([]);
  };

  const toggleEditType = (draftId: string, type: QuestionType) => {
    setDrafts(prev => prev.map(d => {
      if (d.id !== draftId) return d;
      const types = d.enabledTypes.includes(type)
        ? d.enabledTypes.filter(t => t !== type)
        : [...d.enabledTypes, type];
      return { ...d, enabledTypes: types };
    }));
  };

  const finishedItemsCount = drafts.filter(d => d.status === 'done').length;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 mb-6">
      <div className="flex items-center gap-4 mb-6 border-b border-gray-100 pb-2">
        <button onClick={() => setActiveTab(EntryType.WORD)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.WORD ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <Type className="w-4 h-4" /> 生字词录入
        </button>
        <button onClick={() => setActiveTab(EntryType.POEM)} className={`flex items-center gap-2 pb-2 text-sm font-bold transition-colors border-b-2 ${activeTab === EntryType.POEM ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
          <ScrollText className="w-4 h-4" /> 古诗词录入
        </button>
      </div>

      {activeTab === EntryType.WORD ? (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="relative mb-4">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="输入字词，或录入对：'改变 vs 改善'"
              className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[100px] resize-y"
            />
          </div>
          <div className="flex flex-wrap items-center gap-4 mb-4">
            <span className="text-sm text-gray-600 font-medium">默认考点(必选):</span>
            {[QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH].map(t => (
               <label key={t} className="flex items-center space-x-2 cursor-pointer select-none">
                 <input type="checkbox" checked={defaultTypes.includes(t)} onChange={() => setDefaultTypes(prev => prev.includes(t) ? prev.filter(x => x !== t) : [...prev, t])} className="w-4 h-4 text-primary rounded border-gray-300" />
                 <span className="text-sm text-gray-700 font-medium">{{ [QuestionType.PINYIN]: '注音', [QuestionType.DICTATION]: '书写', [QuestionType.DEFINITION]: '释义', [QuestionType.DEFINITION_MATCH]: '辨析' }[t]}</span>
               </label>
            ))}
          </div>
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">
               {processingStatus && <span className="flex items-center text-primary font-medium"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}
             </div>
             <button onClick={handleAnalyzeWords} disabled={isProcessing || !inputText.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-bold transition-all transform active:scale-95 disabled:opacity-50 disabled:scale-100 shadow-md">开始分析</button>
          </div>
        </div>
      ) : (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <textarea value={poemInput} onChange={(e) => setPoemInput(e.target.value)} placeholder="输入诗名或全诗内容。" className="w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary outline-none min-h-[120px]" />
          <div className="flex justify-between items-center border-t pt-3">
             <div className="text-sm text-gray-500">{processingStatus && <span className="flex items-center text-primary font-medium"><Loader2 className="w-4 h-4 mr-2 animate-spin" /> {processingStatus}</span>}</div>
             <button onClick={async () => {
                setIsProcessing(true);
                try {
                  const res = await analyzePoem(poemInput);
                  if (res) {
                    setDrafts([{ id: crypto.randomUUID(), word: res.word, analysis: res, enabledTypes: [QuestionType.POEM_FILL, QuestionType.POEM_DEFINITION], status: 'done', type: EntryType.POEM }]);
                    setPoemInput('');
                  }
                } finally { setIsProcessing(false); }
             }} disabled={isProcessing || !poemInput.trim()} className="bg-primary hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-bold shadow-md disabled:opacity-50">分析古诗</button>
          </div>
        </div>
      )}

      {drafts.length > 0 && (
        <div className="mt-8 border-t border-gray-100 pt-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-md font-bold text-gray-800">识别进度 ({finishedItemsCount}/{drafts.length})</h3>
            <div className="flex gap-2">
              <button onClick={handleSaveAll} disabled={isProcessing || finishedItemsCount === 0} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-bold transition-colors flex items-center shadow-sm disabled:opacity-50"><CheckCircle className="w-4 h-4 mr-2" /> 确认入库</button>
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto pr-2">
            {drafts.map((draft) => (
              <div key={draft.id} className={`rounded-lg p-4 border relative group transition-all duration-300 ${draft.status === 'error' ? 'bg-red-50 border-red-200' : draft.status === 'analyzing' ? 'bg-indigo-50 border-indigo-200 shadow-md' : 'bg-gray-50 border-gray-200'}`}>
                <button onClick={() => setDrafts(prev => prev.filter(d => d.id !== draft.id))} className="absolute top-2 right-2 text-gray-400 hover:text-red-500 transition-colors"><X className="w-4 h-4" /></button>
                <div className="flex flex-col gap-1">
                  <h4 className="font-bold text-gray-900 flex items-center gap-2">
                    {draft.word} 
                    {draft.status === 'done' && draft.analysis?.pinyin && <span className="text-primary text-sm font-normal">{draft.analysis.pinyin}</span>}
                    {draft.status === 'done' && <CheckCircle className="w-4 h-4 text-green-500" />}
                  </h4>
                  <div className="flex flex-wrap gap-1 mt-2">
                    {draft.status === 'done' ? (
                      <>
                        {draft.type === EntryType.WORD ? (
                          <>
                            {['注音', '书写', '释义', '辨析'].map((label, idx) => {
                              const type = [QuestionType.PINYIN, QuestionType.DICTATION, QuestionType.DEFINITION, QuestionType.DEFINITION_MATCH][idx];
                              // 优化：只要不是对比词，注音和书写始终显示；释义和辨析也始终显示，但如果缺失数据会变灰提示。
                              const isComparison = draft.word.includes(' vs ') || draft.word.includes('/');
                              const hasData = (idx === 0 || idx === 1) ? !isComparison : (idx === 2 ? !!draft.analysis?.definitionData : !!draft.analysis?.definitionMatchData);

                              if (isComparison && (idx === 0 || idx === 1)) return null;

                              return (
                                <button 
                                  key={type} 
                                  onClick={() => toggleEditType(draft.id, type)} 
                                  className={`px-2 py-0.5 text-[10px] font-bold rounded border transition-colors flex items-center gap-1 ${draft.enabledTypes.includes(type) ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'} ${!hasData ? 'opacity-50' : ''}`}
                                >
                                  {label}
                                  {!hasData && <Info className="w-2 h-2" title="AI未返回此项数据" />}
                                </button>
                              );
                            })}
                          </>
                        ) : (
                          <span className="text-[10px] text-gray-500 italic">古诗分析完成</span>
                        )}
                      </>
                    ) : (
                      <div className="flex flex-col gap-1 w-full">
                        <span className="text-xs flex items-center text-gray-500 font-medium">
                          {draft.status === 'analyzing' && <><Loader2 className="w-3 h-3 mr-1.5 animate-spin text-primary" /> 正在深度学习词义...</>}
                          {draft.status === 'pending' && <span className="text-gray-400">队列排队中</span>}
                          {draft.status === 'error' && <><AlertCircle className="w-3 h-3 mr-1.5 text-red-500" /> 分析中断</>}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default WordEntryForm;

import React, { useState, useMemo } from 'react';
import { WordEntry, QuestionType, EntryType, TestStatus } from '../types';
import { Trash2, Calendar, Edit2, Check, X, ChevronDown, ScrollText, Filter, CheckCircle2, XCircle, HelpCircle, AlertTriangle } from 'lucide-react';

interface WordListProps {
  words: WordEntry[];
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<WordEntry>) => void;
}

const PAGE_SIZE = 24;

const WordList: React.FC<WordListProps> = ({ words, onDelete, onUpdate }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editState, setEditState] = useState<WordEntry | null>(null);
  const [page, setPage] = useState(1);

  // Filters
  const [filterStatus, setFilterStatus] = useState<TestStatus | 'ALL'>('ALL');
  const [filterDifficulty, setFilterDifficulty] = useState<'ALL' | 'HARD' | 'NORMAL'>('ALL');
  const [filterType, setFilterType] = useState<EntryType | 'ALL'>('ALL');

  // Selection
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // --- Filtering Logic ---
  const filteredWords = useMemo(() => {
    return words.filter(w => {
      if (filterType !== 'ALL' && w.type !== filterType) return false;
      if (filterStatus !== 'ALL' && w.testStatus !== filterStatus) return false;
      if (filterDifficulty === 'HARD' && !w.passedAfterRetries) return false;
      if (filterDifficulty === 'NORMAL' && w.passedAfterRetries) return false; // Normal means passed easily or failed/untested
      return true;
    });
  }, [words, filterType, filterStatus, filterDifficulty]);

  const displayedWords = filteredWords.slice(0, page * PAGE_SIZE);
  const hasMore = filteredWords.length > displayedWords.length;

  // --- Selection Logic ---
  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const selectAll = () => {
    if (selectedIds.size === displayedWords.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(displayedWords.map(w => w.id)));
    }
  };

  // --- Bulk Actions ---
  const handleBulkUpdateStatus = (newStatus: TestStatus) => {
    if (selectedIds.size === 0) return;

    // We iterate selected items and apply the transition logic
    selectedIds.forEach(id => {
      const word = words.find(w => w.id === id);
      if (!word) return;

      // Logic: 
      // Untested -> Passed => passedAfterRetries = false
      // Failed -> Passed => passedAfterRetries = true
      // Passed -> Failed => Status Failed (keep passedAfterRetries as is or reset? Usually keep history or reset. Let's keep logic simple: Failed is Failed).

      let updates: Partial<WordEntry> = { testStatus: newStatus };

      if (newStatus === TestStatus.PASSED) {
        if (word.testStatus === TestStatus.UNTESTED) {
           updates.passedAfterRetries = false;
        } else if (word.testStatus === TestStatus.FAILED) {
           updates.passedAfterRetries = true;
        }
        // If already passed, do nothing or update anyway.
      }

      onUpdate(id, updates);
    });
    setSelectedIds(new Set());
  };

  // --- Individual Edit Logic ---
  const startEdit = (word: WordEntry) => {
    setEditingId(word.id);
    setEditState({ ...word });
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditState(null);
  };

  const saveEdit = () => {
    if (editState) {
      onUpdate(editState.id, { enabledTypes: editState.enabledTypes });
    }
    setEditingId(null);
    setEditState(null);
  };

  const toggleEditType = (type: QuestionType) => {
    if (!editState) return;
    const current = editState.enabledTypes;
    const next = current.includes(type)
      ? current.filter(t => t !== type)
      : [...current, type];
    setEditState({ ...editState, enabledTypes: next });
  };

  const handleLoadMore = () => {
    setPage(p => p + 1);
  };

  // --- Render Helpers ---
  const getStatusIcon = (status: TestStatus) => {
    switch (status) {
      case TestStatus.PASSED: return <CheckCircle2 className="w-4 h-4 text-green-500" />;
      case TestStatus.FAILED: return <XCircle className="w-4 h-4 text-red-500" />;
      default: return <HelpCircle className="w-4 h-4 text-gray-300" />;
    }
  };

  if (words.length === 0) {
    return (
      <div className="text-center py-12 bg-gray-50 rounded-xl border border-dashed border-gray-300">
        <p className="text-gray-400">暂无错题，请在上方录入</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Filter Toolbar */}
      <div className="bg-white p-3 rounded-lg border border-gray-200 shadow-sm flex flex-wrap gap-4 items-center justify-between">
         <div className="flex flex-wrap gap-2 items-center">
            <div className="flex items-center gap-1 text-gray-600 text-sm mr-2">
              <Filter className="w-4 h-4" /> 筛选:
            </div>

            <select 
              value={filterType} 
              onChange={e => setFilterType(e.target.value as any)}
              className="text-sm border-gray-300 rounded-md focus:ring-primary focus:border-primary"
            >
              <option value="ALL">全部类型</option>
              <option value={EntryType.WORD}>生字词</option>
              <option value={EntryType.POEM}>古诗词</option>
            </select>

            <select 
              value={filterStatus} 
              onChange={e => setFilterStatus(e.target.value as any)}
              className="text-sm border-gray-300 rounded-md focus:ring-primary focus:border-primary"
            >
              <option value="ALL">全部状态</option>
              <option value={TestStatus.UNTESTED}>未测试</option>
              <option value={TestStatus.FAILED}>未通过</option>
              <option value={TestStatus.PASSED}>已通过</option>
            </select>

            <select 
              value={filterDifficulty} 
              onChange={e => setFilterDifficulty(e.target.value as any)}
              className="text-sm border-gray-300 rounded-md focus:ring-primary focus:border-primary"
            >
              <option value="ALL">全部难度</option>
              <option value="HARD">困难 (多次重测)</option>
              <option value="NORMAL">普通</option>
            </select>
         </div>

         <div className="text-sm text-gray-500">
           显示 {filteredWords.length} 条
         </div>
      </div>

      {/* Bulk Actions & Selection Header */}
      <div className="flex items-center justify-between bg-gray-50 px-4 py-2 rounded-t-lg border-b border-gray-200">
         <label className="flex items-center space-x-2 cursor-pointer select-none text-sm text-gray-600 font-medium">
            <input 
              type="checkbox" 
              checked={displayedWords.length > 0 && selectedIds.size === displayedWords.length}
              onChange={selectAll}
              className="rounded text-primary focus:ring-primary"
            />
            <span>全选本页</span>
         </label>

         {selectedIds.size > 0 && (
           <div className="flex items-center gap-2 animate-in fade-in duration-200">
              <span className="text-sm text-gray-600 mr-2">已选 {selectedIds.size} 项:</span>
              <button 
                onClick={() => handleBulkUpdateStatus(TestStatus.PASSED)}
                className="text-xs bg-green-100 text-green-700 px-3 py-1.5 rounded-full hover:bg-green-200 font-medium flex items-center"
              >
                <CheckCircle2 className="w-3 h-3 mr-1" /> 标记通过
              </button>
              <button 
                onClick={() => handleBulkUpdateStatus(TestStatus.FAILED)}
                className="text-xs bg-red-100 text-red-700 px-3 py-1.5 rounded-full hover:bg-red-200 font-medium flex items-center"
              >
                <XCircle className="w-3 h-3 mr-1" /> 标记未过
              </button>
           </div>
         )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {displayedWords.map((word) => {
          const isEditing = editingId === word.id;
          const displayWord = isEditing && editState ? editState : word;
          const isPoem = word.type === EntryType.POEM;
          const isSelected = selectedIds.has(word.id);

          return (
            <div 
              key={word.id} 
              className={`bg-white p-4 rounded-lg border shadow-sm transition-all group relative ${isEditing ? 'border-primary ring-1 ring-primary' : isSelected ? 'border-primary bg-indigo-50/10' : 'border-gray-100 hover:shadow-md'}`}
            >
              {/* Checkbox Overlay */}
              <div className={`absolute top-3 left-3 z-10 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'} transition-opacity`}>
                 <input 
                   type="checkbox" 
                   checked={isSelected}
                   onChange={() => toggleSelection(word.id)}
                   className="w-5 h-5 rounded border-gray-300 text-primary focus:ring-primary shadow-sm"
                 />
              </div>

              {/* Status Badge */}
              <div className="absolute top-3 right-12 flex items-center gap-1">
                 {word.passedAfterRetries && (
                   <span className="bg-orange-100 text-orange-700 text-[10px] px-1.5 py-0.5 rounded font-bold border border-orange-200 flex items-center">
                     <AlertTriangle className="w-3 h-3 mr-1" /> 困难
                   </span>
                 )}
                 <div className="flex items-center gap-1 bg-gray-50 px-2 py-0.5 rounded-full border border-gray-100">
                    {getStatusIcon(word.testStatus)}
                    <span className={`text-xs font-medium ${
                      word.testStatus === TestStatus.PASSED ? 'text-green-600' : 
                      word.testStatus === TestStatus.FAILED ? 'text-red-600' : 'text-gray-400'
                    }`}>
                      {word.testStatus === TestStatus.PASSED ? '已通过' : 
                       word.testStatus === TestStatus.FAILED ? '未通过' : '未测试'}
                    </span>
                 </div>
              </div>

              {/* Delete Button (Keep original position but shift slightly) */}
              <button 
                  onClick={() => onDelete(word.id)} 
                  className={`absolute top-3 right-3 p-1.5 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded transition-opacity ${isEditing ? 'hidden' : 'opacity-0 group-hover:opacity-100'}`}
                >
                  <Trash2 className="w-4 h-4" />
                </button>


              <div className="flex justify-between items-start mb-2 mt-6 pl-1">
                <div>
                  <h4 className="text-xl font-bold text-gray-800 font-serif flex items-center gap-2">
                    {isPoem && <ScrollText className="w-4 h-4 text-secondary" />}
                    {word.word}
                  </h4>
                  {isPoem ? (
                     <p className="text-gray-500 text-sm">[{word.poemData?.dynasty}] {word.poemData?.author}</p>
                  ) : (
                     <p className="text-primary text-sm font-medium">{word.pinyin}</p>
                  )}
                </div>

                <div className="flex items-center gap-1 self-start">
                  {isEditing ? (
                    <>
                      <button onClick={saveEdit} className="p-1.5 text-green-600 hover:bg-green-50 rounded"><Check className="w-4 h-4" /></button>
                      <button onClick={cancelEdit} className="p-1.5 text-gray-400 hover:bg-gray-100 rounded"><X className="w-4 h-4" /></button>
                    </>
                  ) : (
                    <button onClick={() => startEdit(word)} className="p-1.5 text-gray-300 hover:text-primary hover:bg-indigo-50 rounded opacity-0 group-hover:opacity-100"><Edit2 className="w-4 h-4" /></button>
                  )}
                </div>
              </div>

              {isPoem && word.poemData && (
                <div className="mb-2 text-sm text-gray-500 italic font-kai max-h-48 overflow-y-auto border-l-2 border-gray-100 pl-2">
                  {word.poemData.lines.map((line, idx) => (
                    <div key={idx} className="leading-relaxed">{line}</div>
                  ))}
                </div>
              )}

              <div className="flex flex-wrap gap-2 mb-2 min-h-[24px] items-center">
                {isEditing ? (
                  <>
                    <span className="text-xs text-gray-400 mr-1">考点:</span>
                    {!isPoem && (
                      <>
                        <button onClick={() => toggleEditType(QuestionType.PINYIN)} className={`text-xs px-2 py-1 rounded-full border ${displayWord.enabledTypes.includes(QuestionType.PINYIN) ? 'bg-blue-100 text-blue-700' : 'bg-white'}`}>注音</button>
                        <button onClick={() => toggleEditType(QuestionType.DICTATION)} className={`text-xs px-2 py-1 rounded-full border ${displayWord.enabledTypes.includes(QuestionType.DICTATION) ? 'bg-blue-100 text-blue-700' : 'bg-white'}`}>书写</button>
                        {word.definitionData && <button onClick={() => toggleEditType(QuestionType.DEFINITION)} className={`text-xs px-2 py-1 rounded-full border ${displayWord.enabledTypes.includes(QuestionType.DEFINITION) ? 'bg-blue-100 text-blue-700' : 'bg-white'}`}>释义</button>}
                        {word.definitionMatchData && <button onClick={() => toggleEditType(QuestionType.DEFINITION_MATCH)} className={`text-xs px-2 py-1 rounded-full border ${displayWord.enabledTypes.includes(QuestionType.DEFINITION_MATCH) ? 'bg-blue-100 text-blue-700' : 'bg-white'}`}>辨析</button>}
                      </>
                    )}
                    {isPoem && (
                       <>
                         <button onClick={() => toggleEditType(QuestionType.POEM_FILL)} className={`text-xs px-2 py-1 rounded-full border ${displayWord.enabledTypes.includes(QuestionType.POEM_FILL) ? 'bg-blue-100 text-blue-700' : 'bg-white'}`}>默写</button>
                         <button onClick={() => toggleEditType(QuestionType.POEM_DEFINITION)} className={`text-xs px-2 py-1 rounded-full border ${displayWord.enabledTypes.includes(QuestionType.POEM_DEFINITION) ? 'bg-blue-100 text-blue-700' : 'bg-white'}`}>释义</button>
                       </>
                    )}
                  </>
                ) : (
                  <>
                    {displayWord.enabledTypes.map(t => {
                      const labels: Record<string, string> = {
                        [QuestionType.PINYIN]: '注音',
                        [QuestionType.DICTATION]: '书写',
                        [QuestionType.DEFINITION]: '释义',
                        [QuestionType.DEFINITION_MATCH]: '辨析',
                        [QuestionType.POEM_FILL]: '默写',
                        [QuestionType.POEM_DEFINITION]: '释义'
                      };
                      return <span key={t} className="text-[10px] px-2 py-0.5 bg-gray-100 text-gray-600 rounded">{labels[t]}</span>;
                    })}
                  </>
                )}
              </div>

              <div className="flex items-center text-xs text-gray-400 mt-2 border-t pt-2">
                <Calendar className="w-3 h-3 mr-1" />
                {new Date(word.createdAt).toLocaleString('zh-CN', { hour12: false })}
              </div>
            </div>
          );
        })}
      </div>

      {hasMore && (
        <div className="flex justify-center pt-4 pb-8">
          <button
            onClick={handleLoadMore}
            className="flex items-center gap-2 bg-white border border-gray-300 text-gray-600 px-6 py-2 rounded-full hover:bg-gray-50 transition-colors shadow-sm"
          >
            <ChevronDown className="w-4 h-4" />
            加载更多
          </button>
        </div>
      )}
    </div>
  );
};

export default WordList;

import React, { useState, useEffect, useRef } from 'react';
import { BookOpen, FileText, Settings, Database, Download, Upload, Trash2, Key, Save, Loader2, CheckCircle, AlertCircle, Globe, Info } from 'lucide-react';
import WordEntryForm from './components/WordEntryForm';
import WordList from './components/WordList';
import ExamGenerator from './components/ExamGenerator';
import { WordEntry, EntryType, TestStatus } from './types';

enum View {
  HOME = 'HOME',
  EXAM = 'EXAM',
}

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [words, setWords] = useState<WordEntry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [hasPaidKey, setHasPaidKey] = useState(false);
  const [isAiStudioEnv, setIsAiStudioEnv] = useState(false);
  const [isKeyActionLoading, setIsKeyActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- 检查环境与密钥状态 ---
  const checkEnvironment = async () => {
    const isEnv = !!(window.aistudio && typeof window.aistudio.openSelectKey === 'function');
    setIsAiStudioEnv(isEnv);

    if (isEnv && window.aistudio) {
      try {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasPaidKey(hasKey);
      } catch (e) {
        console.warn("Failed to check API key status");
      }
    }
  };

  const handleSelectKey = async () => {
    if (isAiStudioEnv && window.aistudio) {
      try {
        setIsKeyActionLoading(true);
        await window.aistudio.openSelectKey();
        setHasPaidKey(true);
        alert("请在弹出的官方对话框中选择您的付费项目密钥。");
      } catch (err) {
        console.error("Failed to open key selector", err);
      } finally {
        setIsKeyActionLoading(false);
      }
    }
  };

  const fetchWords = async () => {
    try {
      setIsLoading(true);
      const res = await fetch('/api/words');
      if (res.ok) {
        const data = await res.json();
        setWords(data);
      } else {
        const saved = localStorage.getItem('yuwen_words');
        if (saved) setWords(JSON.parse(saved));
      }
    } catch (e) {
      console.error("Fetch error", e);
    } finally {
      setIsLoading(false);
    }
  };

  const addWordToBackend = async (entry: WordEntry) => {
    try {
      await fetch('/api/words', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(entry)
      });
    } catch (e) { console.error("Add error", e); }
  };

  const updateWordInBackend = async (id: string, updates: Partial<WordEntry>) => {
    try {
      await fetch('/api/words', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, ...updates })
      });
    } catch (e) { console.error("Update error", e); }
  };

  const deleteWordFromBackend = async (id: string) => {
    try {
      await fetch(`/api/words?id=${id}`, { method: 'DELETE' });
    } catch (e) { console.error("Delete error", e); }
  };

  const deleteAllWordsFromBackend = async () => {
    try {
      // 传递 clearAll 参数以触发批量删除
      await fetch(`/api/words?action=clear`, { method: 'DELETE' });
    } catch (e) { console.error("Clear all error", e); }
  };

  useEffect(() => {
    fetchWords();
    checkEnvironment();
    // 轮询检查一次，防止 aistudio 对象注入延迟
    const timer = setTimeout(checkEnvironment, 1000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoading && words.length > 0) {
      localStorage.setItem('yuwen_words', JSON.stringify(words));
    }
  }, [words, isLoading]);

  const handleAddWord = (entry: WordEntry) => {
    const newEntry = { ...entry, testStatus: TestStatus.UNTESTED, passedAfterRetries: false };
