import pool from './db';

export default async function handler(req, res) {
  // CORS Handling
  res.setHeader('Access-Control-Allow-Credentials', true);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS,PATCH,DELETE,POST,PUT');
  res.setHeader(
    'Access-Control-Allow-Headers',
    'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version'
  );

  if (req.method === 'OPTIONS') {
    res.status(200).end();
    return;
  }

  try {
    const connection = await pool.getConnection();

    try {
      if (req.method === 'GET') {
        const [rows] = await connection.query('SELECT * FROM words ORDER BY created_at DESC');
        const words = rows.map(row => ({
          id: row.id,
          type: row.type,
          word: row.word,
          pinyin: row.pinyin,
          createdAt: Number(row.created_at),
          definitionData: row.definition_data,
          definitionMatchData: row.definition_match_data,
          poemData: row.poem_data,
          enabledTypes: row.enabled_types || [],
          testStatus: row.test_status || 'UNTESTED',
          passedAfterRetries: Boolean(row.passed_after_retries)
        }));
        return res.status(200).json(words);
      }

      if (req.method === 'POST') {
        const entry = req.body;
        await connection.query(
          `INSERT INTO words (id, type, word, pinyin, created_at, definition_data, definition_match_data, poem_data, enabled_types, test_status, passed_after_retries) 
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            entry.id,
            entry.type,
            entry.word,
            entry.pinyin,
            entry.createdAt,
            JSON.stringify(entry.definitionData || null),
            JSON.stringify(entry.definitionMatchData || null),
            JSON.stringify(entry.poemData || null),
            JSON.stringify(entry.enabledTypes || []),
            entry.testStatus || 'UNTESTED',
            entry.passedAfterRetries || false
          ]
        );
        return res.status(201).json({ success: true });
      }

      if (req.method === 'PATCH') {
        const { id } = req.query; // Or extract from body if preferred, but usually ID is in path or query
        // Vercel functions often use query for path params like /api/words?id=123
        const targetId = id || req.body.id;

        if (!targetId) return res.status(400).json({ error: "Missing ID" });

        const updates = req.body;
        const fields = [];
        const values = [];

        if (updates.enabledTypes !== undefined) {
          fields.push('enabled_types = ?');
          values.push(JSON.stringify(updates.enabledTypes));
        }
        if (updates.testStatus !== undefined) {
          fields.push('test_status = ?');
          values.push(updates.testStatus);
        }
        if (updates.passedAfterRetries !== undefined) {
          fields.push('passed_after_retries = ?');
          values.push(updates.passedAfterRetries ? 1 : 0);
        }
        // 新增：支持更新释义数据（含例句）
        if (updates.definitionData !== undefined) {
          fields.push('definition_data = ?');
          values.push(JSON.stringify(updates.definitionData));
        }

        if (fields.length === 0) return res.status(200).json({ message: "No updates" });

        values.push(targetId);

        await connection.query(
          `UPDATE words SET ${fields.join(', ')} WHERE id = ?`,
          values
        );
        return res.status(200).json({ success: true });
      }

      if (req.method === 'DELETE') {
        const { id, action } = req.query; // /api/words?id=xyz or /api/words?action=clear

        if (action === 'clear') {
           await connection.query('DELETE FROM words');
           return res.status(200).json({ success: true });
        }

        if (!id) return res.status(400).json({ error: "Missing ID" });
        await connection.query('DELETE FROM words WHERE id = ?', [id]);
        return res.status(200).json({ success: true });
      }

    } finally {
      connection.release();
    }

  } catch (error) {
    console.error("Database Error:", error);
    return res.status(500).json({ error: "Database operation failed", details: error.message });
  }
}

import React, { useState, useMemo, useEffect } from 'react';
import { WordEntry, EntryType } from '../types';
import { ArrowLeft, ChevronLeft, ChevronRight, RotateCw, Filter, BookOpen, Quote, Edit2, Save, X } from 'lucide-react';

interface ReviewFlashcardsProps {
  words: WordEntry[];
  onBack: () => void;
  onUpdate: (id: string, updates: Partial<WordEntry>) => void;
}

const ReviewFlashcards: React.FC<ReviewFlashcardsProps> = ({ words, onBack, onUpdate }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>('');

  // Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editDefinition, setEditDefinition] = useState('');
  const [editExample, setEditExample] = useState('');

  const availableDates = useMemo(() => {
    const dates = new Set(words.map(w => new Date(w.createdAt).toLocaleDateString('zh-CN')));
    return Array.from(dates).sort().reverse();
  }, [words]);

  // 只复习生字词
  const filteredWords = useMemo(() => {
    return words.filter(w => {
      if (w.type !== EntryType.WORD) return false;
      if (selectedDate && new Date(w.createdAt).toLocaleDateString('zh-CN') !== selectedDate) return false;
      return true;
    });
  }, [words, selectedDate]);

  const currentWord = filteredWords[currentIndex];

  // Reset state when changing card
  useEffect(() => {
    setIsEditing(false);
    if (currentWord) {
      const defData = currentWord.definitionData;
      // Load existing data or fallback
      const definition = defData?.simpleDefinition 
        || (defData?.options && defData.correctIndex !== undefined ? defData.options[defData.correctIndex] : '')
        || "";
      const example = defData?.exampleSentence || "";

      setEditDefinition(definition);
      setEditExample(example);
    }
  }, [currentWord, currentIndex]);

  const handleNext = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (currentIndex < filteredWords.length - 1) {
      setIsFlipped(false);
      setTimeout(() => setCurrentIndex(c => c + 1), 150);
    }
  };

  const handlePrev = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (currentIndex > 0) {
      setIsFlipped(false);
      setTimeout(() => setCurrentIndex(c => c - 1), 150);
    }
  };

  const handleDateChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedDate(e.target.value);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!currentWord) return;

    const newDefinitionData = {
      ...(currentWord.definitionData || {
        targetChar: currentWord.word[0],
        options: [],
        correctIndex: 0
      }),
      simpleDefinition: editDefinition,
      exampleSentence: editExample
    };

    onUpdate(currentWord.id, { definitionData: newDefinitionData });
    setIsEditing(false);
  };

  const handleStartEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsEditing(true);
  };

  const handleCancelEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsEditing(false);
    // Reset to original values
    const defData = currentWord.definitionData;
    const definition = defData?.simpleDefinition 
      || (defData?.options && defData.correctIndex !== undefined ? defData.options[defData.correctIndex] : '')
      || "";
    const example = defData?.exampleSentence || "";
    setEditDefinition(definition);
    setEditExample(example);
  };

  // 提取显示数据 (用于非编辑模式)
  const displayData = useMemo(() => {
    if (!currentWord) return null;
    const defData = currentWord.definitionData;

    // 优先使用新字段 simpleDefinition，如果没有则尝试从选项中获取
    const definition = defData?.simpleDefinition 
      || (defData?.options ? defData.options[defData.correctIndex] : null)
      || "暂无释义 (点击编辑补充)";

    const example = defData?.exampleSentence || "暂无例句 (点击编辑补充)";

    return {
      word: currentWord.word,
      pinyin: currentWord.pinyin,
      definition,
      example
    };
  }, [currentWord]);

  if (filteredWords.length === 0) {
    return (
      <div className="min-h-screen bg-gray-100 flex flex-col p-6">
        <button onClick={onBack} className="text-gray-500 hover:text-gray-800 flex items-center font-bold mb-8 transition-colors self-start">
          <ArrowLeft className="w-5 h-5 mr-1" /> 返回
        </button>
        <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-400">
          <BookOpen className="w-16 h-16 mb-4 text-gray-300" />
          <p>当前筛选条件下没有可复习的生字词。</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center justify-center p-4 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-64 bg-primary/10 rounded-b-[3rem]"></div>

      {/* Header */}
      <div className="w-full max-w-lg flex items-center justify-between mb-8 z-10 relative">
        <button onClick={onBack} className="text-gray-600 hover:text-gray-900 bg-white/50 p-2 rounded-full backdrop-blur-sm transition-all shadow-sm">
          <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="flex items-center gap-2 bg-white/80 backdrop-blur-md px-3 py-1.5 rounded-full shadow-sm border border-white/50">
           <Filter className="w-4 h-4 text-primary" />
           <select 
             value={selectedDate} 
             onChange={handleDateChange}
             className="bg-transparent text-sm text-gray-700 font-bold focus:outline-none cursor-pointer"
           >
             <option value="">全部题库 ({words.filter(w => w.type === EntryType.WORD).length})</option>
             {availableDates.map(d => <option key={d} value={d}>{d}</option>)}
           </select>
        </div>

        <div className="text-gray-600 font-bold text-sm bg-white/50 px-3 py-1.5 rounded-full">
          {currentIndex + 1} / {filteredWords.length}
        </div>
      </div>

      {/* Main Content Area: Left Button + Card + Right Button */}
      <div className="relative w-full max-w-4xl flex items-center justify-center gap-4 md:gap-12 z-10">

        {/* Prev Button (Left) */}
        <button 
          onClick={handlePrev} 
          disabled={currentIndex === 0}
          className="hidden md:flex p-4 bg-white/80 rounded-full shadow-lg text-gray-700 hover:text-primary disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95 backdrop-blur-sm"
        >
          <ChevronLeft className="w-8 h-8" />
        </button>

        {/* Card Container */}
        <div className="w-full max-w-md aspect-[3/4] relative perspective-1000 group" onClick={() => !isEditing && setIsFlipped(!isFlipped)}>
          <div className={`w-full h-full relative transition-all duration-500 transform-style-3d cursor-pointer shadow-2xl rounded-3xl ${isFlipped ? 'rotate-y-180' : ''}`}>

            {/* Front */}
            <div className="absolute inset-0 bg-white rounded-3xl p-8 flex flex-col items-center justify-center backface-hidden border-2 border-white shadow-inner">
               <div className="flex-1 flex flex-col items-center justify-center gap-6">
                  <span className="text-3xl text-gray-500 font-medium font-sans tracking-widest">{displayData?.pinyin}</span>
                  <h2 className="text-7xl font-bold text-gray-800 font-serif mb-4">{displayData?.word}</h2>
                  <div className="w-16 h-1 bg-primary/20 rounded-full"></div>
               </div>
               <p className="text-gray-400 text-sm mt-auto animate-pulse">点击翻转查看释义</p>
            </div>

            {/* Back */}
            <div className="absolute inset-0 bg-gradient-to-br from-primary to-indigo-700 rounded-3xl p-6 md:p-8 flex flex-col items-center backface-hidden rotate-y-180 text-white shadow-xl">

               {/* Toolbar (Edit/Save) */}
               <div className="w-full flex justify-end mb-2">
                 {isEditing ? (
                   <div className="flex gap-2">
                     <button onClick={handleCancelEdit} className="p-2 bg-white/20 hover:bg-white/30 rounded-full transition-colors" title="取消">
                        <X className="w-4 h-4 text-white" />
                     </button>
                     <button onClick={handleSave} className="p-2 bg-green-500 hover:bg-green-600 rounded-full transition-colors shadow-sm" title="保存">
                        <Save className="w-4 h-4 text-white" />
                     </button>
                   </div>
                 ) : (
                   <button onClick={handleStartEdit} className="p-2 text-white/50 hover:text-white transition-colors" title="编辑释义和例句">
                      <Edit2 className="w-5 h-5" />
                   </button>
                 )}
               </div>

               <div className="flex-1 flex flex-col w-full overflow-y-auto pr-1 custom-scrollbar">
                  <div className="mb-6">
                    <h3 className="flex items-center text-indigo-200 text-sm font-bold uppercase tracking-wider mb-2">
                      <BookOpen className="w-4 h-4 mr-2" /> 释义
                    </h3>
                    {isEditing ? (
                      <textarea
                        value={editDefinition}
                        onChange={(e) => setEditDefinition(e.target.value)}
                        onClick={(e) => e.stopPropagation()}
                        className="w-full bg-white/10 border border-white/20 rounded-lg p-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/50 text-base"
                        rows={3}
                        placeholder="请输入简明释义..."
                      />
                    ) : (
                      <p className="text-xl font-medium leading-relaxed font-serif text-white/95">
                        {displayData?.definition}
                      </p>
                    )}
                  </div>

                  <div className={`bg-white/10 rounded-xl p-4 border border-white/10 ${isEditing ? 'bg-transparent border-0 p-0' : ''}`}>
                    <h3 className="flex items-center text-indigo-200 text-sm font-bold uppercase tracking-wider mb-2">
                      <Quote className="w-4 h-4 mr-2" /> 例句
                    </h3>
                    {isEditing ? (
                      <textarea
                        value={editExample}
                        onChange={(e) => setEditExample(e.target.value)}
                        onClick={(e) => e.stopPropagation()}
                        className="w-full bg-white/10 border border-white/20 rounded-lg p-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/50 text-base font-kai"
                        rows={3}
                        placeholder="请输入通俗例句..."
                      />
                    ) : (
                      <p className="text-lg text-white/90 italic font-kai leading-relaxed">
                        “{displayData?.example}”
                      </p>
                    )}
                  </div>
               </div>

               {!isEditing && (
                 <button onClick={(e) => { e.stopPropagation(); setIsFlipped(false); }} className="mt-4 text-white/50 hover:text-white transition-colors pt-2">
                   <RotateCw className="w-6 h-6" />
                 </button>
               )}
            </div>

          </div>
        </div>

        {/* Next Button (Right) */}
        <button 
          onClick={handleNext} 
          disabled={currentIndex === filteredWords.length - 1}
          className="hidden md:flex p-4 bg-primary rounded-full shadow-lg shadow-primary/30 text-white hover:bg-indigo-500 disabled:opacity-30 disabled:bg-gray-300 disabled:cursor-not-allowed transition-all active:scale-95"
        >
          <ChevronRight className="w-8 h-8" />
        </button>

      </div>

      {/* Mobile Controls (Below Card) */}
      <div className="flex md:hidden items-center gap-8 mt-6 z-10">
        <button 
          onClick={handlePrev} 
          disabled={currentIndex === 0}
          className="p-4 bg-white rounded-full shadow-lg text-gray-700 hover:text-primary disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95"
        >
          <ChevronLeft className="w-6 h-6" />
        </button>
        <button 
          onClick={handleNext} 
          disabled={currentIndex === filteredWords.length - 1}
          className="p-4 bg-primary rounded-full shadow-lg shadow-primary/30 text-white hover:bg-indigo-500 disabled:opacity-30 disabled:bg-gray-300 disabled:cursor-not-allowed transition-all active:scale-95"
        >
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>

      <style>{`
        .perspective-1000 { perspective: 1000px; }
        .transform-style-3d { transform-style: preserve-3d; }
        .backface-hidden { backface-visibility: hidden; }
        .rotate-y-180 { transform: rotateY(180deg); }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: rgba(255,255,255,0.1); }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.3); border-radius: 4px; }
      `}</style>
    </div>
  );
};

export default ReviewFlashcards;

import React, { useState, useEffect, useRef } from 'react';
import { BookOpen, FileText, Settings, Database, Download, Upload, Trash2, Key, Save, Loader2, CheckCircle, AlertCircle, Globe, Info, GraduationCap } from 'lucide-react';
import WordEntryForm from './components/WordEntryForm';
import WordList from './components/WordList';
import ExamGenerator from './components/ExamGenerator';
import ReviewFlashcards from './components/ReviewFlashcards';
import { WordEntry, EntryType, TestStatus } from './types';

enum View {
  HOME = 'HOME',
  EXAM = 'EXAM',
  REVIEW = 'REVIEW',
}

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [words, setWords] = useState<WordEntry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [hasPaidKey, setHasPaidKey] = useState(false);
  const [isAiStudioEnv, setIsAiStudioEnv] = useState(false);
  const [isKeyActionLoading, setIsKeyActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- 检查环境与密钥状态 ---
  const checkEnvironment = async () => {
    const isEnv = !!(window.aistudio && typeof window.aistudio.openSelectKey === 'function');
    setIsAiStudioEnv(isEnv);

    if (isEnv && window.aistudio) {
      try {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasPaidKey(hasKey);
      } catch (e) {
        console.warn("Failed to check API key status");
      }
    }
  };

  const handleSelectKey = async () => {
    if (isAiStudioEnv && window.aistudio) {
      try {
        setIsKeyActionLoading(true);
        await window.aistudio.openSelectKey();
        setHasPaidKey(true);
        alert("请在弹出的官方对话框中选择您的付费项目密钥。");
      } catch (err) {
        console.error("Failed to open key selector", err);
      } finally {
        setIsKeyActionLoading(false);
      }
    }
  };

  const fetchWords = async () => {
    try {
      setIsLoading(true);
      const res = await fetch('/api/words');
      if (res.ok) {
        const data = await res.json();
        setWords(data);
      } else {
        const saved = localStorage.getItem('yuwen_words');
        if (saved) setWords(JSON.parse(saved));
      }
    } catch (e) {
      console.error("Fetch error", e);
    } finally {
      setIsLoading(false);
    }
  };

  const addWordToBackend = async (entry: WordEntry) => {
    try {
      await fetch('/api/words', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(entry)
      });
    } catch (e) { console.error("Add error", e); }
  };

  const updateWordInBackend = async (id: string, updates: Partial<WordEntry>) => {
    try {
      await fetch('/api/words', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, ...updates })
      });
    } catch (e) { console.error("Update error", e); }
  };

  const deleteWordFromBackend = async (id: string) => {
    try {
      await fetch(`/api/words?id=${id}`, { method: 'DELETE' });
    } catch (e) { console.error("Delete error", e); }
  };

  const deleteAllWordsFromBackend = async () => {
    try {
      // 传递 clearAll 参数以触发批量删除
      await fetch(`/api/words?action=clear`, { method: 'DELETE' });
    } catch (e) { console.error("Clear all error", e); }
  };

  useEffect(() => {
    fetchWords();
    checkEnvironment();
    // 轮询检查一次，防止 aistudio 对象注入延迟
    const timer = setTimeout(checkEnvironment, 1000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoading && words.length > 0) {
      localStorage.setItem('yuwen_words', JSON.stringify(words));
    }
  }, [words, isLoading]);

  const handleAddWord = (entry: WordEntry) => {
    const newEntry = { ...entry, testStatus: TestStatus.UNTESTED, passedAfterRetries: false };
    setWords(prev => [newEntry, ...prev]);
    addWordToBackend(newEntry);
  };

  const handleDeleteWord = (id: string) => {
    setWords(prev => prev.filter(w => w.id !== id));
    deleteWordFromBackend(id);
  };

  const handleUpdateWord = (id: string, updates: Partial<WordEntry>) => {
    setWords(prev => prev.map(w => w.id === id ? { ...w, ...updates } : w));
    updateWordInBackend(id, updates);
  };

  const handleExport = () => {
    const dataStr = JSON.stringify(words, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `语文错题本备份_${new Date().toLocaleDateString('zh-CN')}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
          if (confirm(`确定要导入 ${json.length} 条数据吗？`)) {
            const currentIds = new Set(words.map(w => w.id));
            const newWords = json
              .filter((w: any) => !currentIds.has(w.id))
              .map((w: any) => ({ 
                ...w, 
                type: w.type || EntryType.WORD,
                testStatus: w.testStatus || TestStatus.UNTESTED,
                passedAfterRetries: w.passedAfterRetries || false
              }));
            setWords(prev => [...newWords, ...prev]);
            for (const w of newWords) await addWordToBackend(w);
            alert(`成功导入 ${newWords.length} 个新词语！`);
          }
        } else alert("文件格式不正确");
      } catch (err) { alert("无法解析文件"); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleClearAll = async () => {
    if (confirm("确定要清空所有题库数据吗？\n此操作将删除数据库及本地所有记录，且不可恢复！")) {
      if (confirm("再次确认：您确定要删除所有数据吗？")) {
         await deleteAllWordsFromBackend();
         setWords([]);
         localStorage.removeItem('yuwen_words');
         alert("题库已清空");
      }
    }
  };

  if (currentView === View.EXAM) {
    return <ExamGenerator words={words} onBack={() => setCurrentView(View.HOME)} />;
  }

  if (currentView === View.REVIEW) {
    return <ReviewFlashcards words={words} onBack={() => setCurrentView(View.HOME)} onUpdate={handleUpdateWord} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 text-primary font-bold text-xl">
            <BookOpen className="w-6 h-6" />
            <span className="hidden sm:inline">语文错题助手</span>
            <span className="sm:hidden">错题助手</span>
          </div>

          <div className="flex items-center gap-3">
             <button
              onClick={() => setShowSettings(!showSettings)}
              className={`p-2 rounded-lg transition-colors ${showSettings ? 'bg-gray-100 text-gray-900' : 'text-gray-500 hover:bg-gray-50'}`}
             >
               <Settings className="w-5 h-5" />
             </button>

            <button 
              onClick={() => setCurrentView(View.REVIEW)}
              disabled={isLoading || words.length === 0}
              className="flex items-center gap-2 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 px-3 py-2 rounded-lg text-sm font-bold transition-colors disabled:opacity-50"
            >
              <GraduationCap className="w-4 h-4 text-secondary" />
              <span className="hidden sm:inline">复习闪卡</span>
            </button>

            <button 
              onClick={() => setCurrentView(View.EXAM)}
              disabled={isLoading || words.length === 0}
              className="flex items-center gap-2 bg-gray-900 hover:bg-black text-white px-3 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
            >
              <FileText className="w-4 h-4" />
              <span className="hidden sm:inline">生成试卷</span>
              <span className="sm:hidden">试卷</span>
            </button>
          </div>
        </div>

        {showSettings && (
          <div className="bg-white border-b border-gray-200 shadow-sm animate-in slide-in-from-top-2 duration-200 p-4">
            <div className="max-w-5xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <h3 className="font-bold text-gray-700 mb-3 flex items-center">
                  <Key className="w-4 h-4 mr-2" /> AI 接口状态
                </h3>
                <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-sm text-gray-600">运行环境:</span>
                    {isAiStudioEnv ? (
                      <span className="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold flex items-center">
                        <CheckCircle className="w-3 h-3 mr-1" /> AI Studio 预览
                      </span>
                    ) : (
                      <span className="text-[10px] bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full font-bold flex items-center">
                        <Globe className="w-3 h-3 mr-1" /> 独立域名部署
                      </span>
                    )}
                  </div>

                  {isAiStudioEnv ? (
                    <>
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-sm text-gray-600">密钥状态:</span>
                        {hasPaidKey ? (
                          <span className="text-[10px] bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-bold flex items-center">已接入付费项目</span>
                        ) : (
                          <span className="text-[10px] bg-orange-100 text-orange-700 px-2 py-0.5 rounded-full font-bold flex items-center">免费/限制模式</span>
                        )}
                      </div>
                      <button 
                        onClick={handleSelectKey}
                        disabled={isKeyActionLoading}
                        className="w-full py-2 bg-white border border-gray-200 rounded-lg text-sm font-bold text-gray-700 hover:bg-gray-50 transition-colors shadow-sm flex items-center justify-center gap-2 disabled:opacity-50"
                      >
                        {isKeyActionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Key className="w-4 h-4 text-primary" />}
                        切换付费密钥
                      </button>
                    </>
                  ) : (
                    <div className="space-y-3">
                      <div className="p-3 bg-white border border-gray-200 rounded-lg">
                        <p className="text-[11px] text-gray-500 leading-relaxed mb-2 flex items-start">
                          <Info className="w-3 h-3 mr-1.5 mt-0.5 shrink-0 text-primary" />
                          当前在独立域名运行，无法直接弹出密钥选择器。
                        </p>
                        <p className="text-[11px] text-gray-700 font-medium">若需提升分析成功率：</p>
                        <ol className="text-[10px] text-gray-500 list-decimal pl-4 mt-1 space-y-1">
                          <li>前往您的 Vercel/托管平台设置页</li>
                          <li>在 <code className="bg-gray-100 px-1">Environment Variables</code> 中添加 <code className="bg-gray-100 px-1 text-primary">API_KEY</code></li>
                          <li>填入您的付费项目密钥并重新部署</li>
                        </ol>
                      </div>
                    </div>
                  )}
                  <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-[10px] text-primary hover:underline mt-3 block text-center">查看 Google API 计费说明</a>
                </div>
              </div>

              <div>
                <h3 className="font-bold text-gray-700 mb-3 flex items-center">
                  <Database className="w-4 h-4 mr-2" /> 数据管理
                </h3>
                <div className="flex flex-wrap gap-2">
                  <button onClick={handleExport} className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-white border border-gray-300 rounded text-sm hover:bg-gray-50 text-gray-700 font-bold"><Download className="w-4 h-4" /> 导出备份</button>
