import { GoogleGenAI, Type } from "@google/genai";

const itemSchemaProperties = {
  word: { type: Type.STRING, description: "原始词语" },
  pinyin: { type: Type.STRING },
  hasDefinitionQuestion: { type: Type.BOOLEAN, description: "是否生成释义选择题，对于普通词语和成语必须为 true" },
  targetChar: { type: Type.STRING, nullable: true },
  options: { type: Type.ARRAY, items: { type: Type.STRING }, nullable: true, description: "4个释义选项" },
  correctIndex: { type: Type.INTEGER, nullable: true },
  simpleDefinition: { type: Type.STRING, description: "该词语的简明释义，用于复习卡片" },
  exampleSentence: { type: Type.STRING, description: "一个通俗易懂的例句，帮助记忆该词语的意思和用法" },
  hasMatchQuestion: { type: Type.BOOLEAN },
  matchMode: { type: Type.STRING, description: "SAME_AS_TARGET (找字义相同), SYNONYM_CHOICE (选词填空), or TWO_WAY_COMPARE (二选一判断)" },
  matchContext: { type: Type.STRING, nullable: true },
  matchOptions: { type: Type.ARRAY, items: { type: Type.STRING }, nullable: true },
  matchCorrectIndex: { type: Type.INTEGER, nullable: true },
  compareWordA: { type: Type.STRING, nullable: true },
  compareWordB: { type: Type.STRING, nullable: true },
  isSame: { type: Type.BOOLEAN, nullable: true }
};

const batchAnalysisSchema = {
  type: Type.OBJECT,
  properties: {
    results: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: itemSchemaProperties,
        required: ["word", "pinyin", "hasDefinitionQuestion", "hasMatchQuestion", "simpleDefinition", "exampleSentence"]
      }
    }
  },
  required: ["results"]
};

const explanationSchema = {
  type: Type.OBJECT,
  properties: {
    simpleDefinition: { type: Type.STRING, description: "该词语的简明释义" },
    exampleSentence: { type: Type.STRING, description: "一个通俗易懂的例句" }
  },
  required: ["simpleDefinition", "exampleSentence"]
};

const poemSchema = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    dynasty: { type: Type.STRING },
    author: { type: Type.STRING },
    content: { type: Type.STRING },
    lines: { type: Type.ARRAY, items: { type: Type.STRING } },
    fillQuestions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          lineIndex: { type: Type.INTEGER },
          pre: { type: Type.STRING },
          answer: { type: Type.STRING },
          post: { type: Type.STRING },
        }
      }
    },
    definitionQuestions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          lineIndex: { type: Type.INTEGER },
          targetChar: { type: Type.STRING },
          options: { type: Type.ARRAY, items: { type: Type.STRING } },
          correctIndex: { type: Type.INTEGER },
        }
      }
    }
  },
  required: ["title", "author", "lines", "definitionQuestions", "fillQuestions"]
};

const ocrSchema = {
  type: Type.OBJECT,
  properties: {
    words: { type: Type.ARRAY, items: { type: Type.STRING } }
  }
};

const cleanJson = (text) => {
  if (!text) return '{}';
  let cleaned = text.trim();
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    return cleaned.substring(firstBrace, lastBrace + 1);
  }
  return cleaned;
};

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Credentials', true);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS,PATCH,DELETE,POST,PUT');
  res.setHeader('Access-Control-Allow-Headers', 'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version');

  if (req.method === 'OPTIONS') return res.status(200).end();

  const dynamicApiKey = process.env.API_KEY;
  if (!dynamicApiKey) return res.status(500).json({ error: "Server API Key missing." });

  try {
    const ai = new GoogleGenAI({ apiKey: dynamicApiKey });
    const { type, text, words, image } = req.body;

    let model = 'gemini-3-flash-preview';
    let parts = [];
    let schema = null;
    let thinkingBudget = 0;

    if (type === 'batch-words') {
      parts = [{ text: `你是一个资深的语文教育专家。分析：${words.join(', ')}。

      【强制要求】：
      1. 每个词语/成语都【必须】生成释义选择题 (hasDefinitionQuestion: true)，给出词语的准确含义及3个干扰项。
      2. 每个词语/成语都【必须】生成简明释义 (simpleDefinition) 和通俗例句 (exampleSentence)，用于制作复习闪卡。
      3. 每个词语/成语都【必须】生成辨析题 (hasMatchQuestion: true)。
      4. 如果是成语（如“低声细语”），重点分析其整体含义。
      5. 如果是对比词（如“改变 vs 改善”），使用 SYNONYM_CHOICE 模式。

      请确保 results 数组中每个对象都完整包含 definitionData 和 matchData 相关字段。` }];
      schema = batchAnalysisSchema;
      thinkingBudget = 4000;
    } else if (type === 'poem') {
      parts = [{ text: `你是一个资深的语文教育专家。分析古诗词 "${text}"...` }];
      schema = poemSchema;
      thinkingBudget = 10000;
    } else if (type === 'explain-word') {
      parts = [{ text: `你是一个语文老师。请为小学/初中学生解释生字词 "${text}"。
      要求：
      1. simpleDefinition: 用简洁的语言解释意思（20字以内）。
      2. exampleSentence: 造一个通俗易懂的例句，帮助理解用法。` }];
      schema = explanationSchema;
      thinkingBudget = 0; // 简单任务无需深度思考
    } else if (type === 'ocr') {
      parts = [{ inlineData: { mimeType: 'image/jpeg', data: image } }, { text: "提取图中的所有中文生词、成语。" }];
      schema = ocrSchema;
    }

    const response = await ai.models.generateContent({
      model: model,
      contents: { parts },
      config: { 
        responseMimeType: 'application/json', 
        responseSchema: schema,
        thinkingConfig: { thinkingBudget }
      }
    });

    return res.status(200).json(JSON.parse(cleanJson(response.text)));
  } catch (error) {
    return res.status(500).json({ error: error.message });
  }
}

import { AnalysisResult, EntryType, MatchMode } from "../types";

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const analyzeWithGeminiBackend = async (payload: any, retries = 4) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60000); 

  try {
    const response = await fetch('/api/analyze', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: controller.signal
    });

    clearTimeout(timeoutId);

    // 处理频率限制 (Rate Limit)
    if (response.status === 429 && retries > 0) {
      // 随着重试次数增加，等待时间变长 (10s, 20s, 30s...)
      const waitTime = (5 - retries) * 10000; 
      console.warn(`AI 频率限制，将在 ${waitTime/1000} 秒后重试...`);
      await delay(waitTime);
      return analyzeWithGeminiBackend(payload, retries - 1);
    }

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `API failure: ${response.status}`);
    }

    return await response.json();
  } catch (error: any) {
    clearTimeout(timeoutId);
    if (retries > 0 && (error.name === 'AbortError' || error.message.includes('timeout') || error.message.includes('500'))) {
      await delay(3000);
      return analyzeWithGeminiBackend(payload, retries - 1);
    }
    throw error;
  }
};

export const analyzeWordsBatch = async (words: string[]): Promise<AnalysisResult[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'batch-words', words });
    if (data.results && Array.isArray(data.results)) {
      return data.results.map((item: any) => mapDataToResult(item));
    }
    return [];
  } catch (error) {
    console.error("Batch Analysis Error:", error);
    throw error;
  }
};

export const analyzeWord = async (word: string): Promise<AnalysisResult> => {
  const res = await analyzeWordsBatch([word]);
  return res[0];
};

export const explainWord = async (word: string): Promise<{simpleDefinition: string, exampleSentence: string} | null> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'explain-word', text: word });
    return data;
  } catch (error) {
    console.error("Explain Word Error:", error);
    return null;
  }
};

export const analyzePoem = async (input: string): Promise<AnalysisResult | null> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'poem', text: input });
    return {
      type: EntryType.POEM,
      word: data.title,
      pinyin: data.author,
      definitionData: null,
      definitionMatchData: null,
      poemData: {
        title: data.title,
        dynasty: data.dynasty,
        author: data.author,
        content: data.content,
        lines: data.lines || [],
        fillAnswers: data.fillQuestions || [],
        definitionQuestions: data.definitionQuestions || []
      }
    };
  } catch (error) {
    return null;
  }
};

export const extractWordsFromImage = async (base64Data: string, mimeType: string): Promise<string[]> => {
  try {
    const data = await analyzeWithGeminiBackend({ type: 'ocr', image: base64Data });
    return data.words || [];
  } catch (error) {
    return [];
  }
};

function mapDataToResult(data: any): AnalysisResult {
  let matchData = null;
  if (data.hasMatchQuestion) {
    matchData = {
      mode: data.matchMode as MatchMode || MatchMode.SAME_AS_TARGET,
      targetChar: data.targetChar || data.word?.[0] || '?',
      context: data.matchContext,
      options: data.matchOptions,
      correctIndex: data.matchCorrectIndex,
      compareWordA: data.compareWordA,
      compareWordB: data.compareWordB,
      isSame: data.isSame
    };
  }

  // 始终尝试构建 definitionData，即使 hasDefinitionQuestion 为 false，也要保存 simpleDefinition 和 exampleSentence
  const defData = {
    targetChar: data.targetChar || data.word?.[0] || '?',
    options: data.options || [],
    correctIndex: typeof data.correctIndex === 'number' ? data.correctIndex : 0,
    simpleDefinition: data.simpleDefinition,
    exampleSentence: data.exampleSentence
  };

  return {
    type: EntryType.WORD,
    word: data.word,
    pinyin: data.pinyin,
    definitionData: defData,
    definitionMatchData: matchData
  };
}

import React, { useState, useMemo, useEffect } from 'react';
import { WordEntry, EntryType } from '../types';
import { ArrowLeft, ChevronLeft, ChevronRight, RotateCw, Filter, BookOpen, Quote, Edit2, Save, X, Wand2, Loader2 } from 'lucide-react';
import { explainWord } from '../services/geminiService';

interface ReviewFlashcardsProps {
  words: WordEntry[];
  onBack: () => void;
  onUpdate: (id: string, updates: Partial<WordEntry>) => void;
}

const ReviewFlashcards: React.FC<ReviewFlashcardsProps> = ({ words, onBack, onUpdate }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>('');

  // Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editDefinition, setEditDefinition] = useState('');
  const [editExample, setEditExample] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const availableDates = useMemo(() => {
    const dates = new Set(words.map(w => new Date(w.createdAt).toLocaleDateString('zh-CN')));
    return Array.from(dates).sort().reverse();
  }, [words]);

  // 只复习生字词
  const filteredWords = useMemo(() => {
    return words.filter(w => {
      if (w.type !== EntryType.WORD) return false;
      if (selectedDate && new Date(w.createdAt).toLocaleDateString('zh-CN') !== selectedDate) return false;
      return true;
    });
  }, [words, selectedDate]);

  const currentWord = filteredWords[currentIndex];

  // Reset state when changing card
  useEffect(() => {
    setIsEditing(false);
    setIsGenerating(false);
    if (currentWord) {
      const defData = currentWord.definitionData;
      // Load existing data or fallback
      const definition = defData?.simpleDefinition 
        || (defData?.options && defData.correctIndex !== undefined ? defData.options[defData.correctIndex] : '')
        || "";
      const example = defData?.exampleSentence || "";

      setEditDefinition(definition);
      setEditExample(example);
    }
  }, [currentWord, currentIndex]);

  const handleNext = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (currentIndex < filteredWords.length - 1) {
      setIsFlipped(false);
      setTimeout(() => setCurrentIndex(c => c + 1), 150);
    }
  };

  const handlePrev = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (currentIndex > 0) {
      setIsFlipped(false);
      setTimeout(() => setCurrentIndex(c => c - 1), 150);
    }
  };

  const handleDateChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedDate(e.target.value);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!currentWord) return;

    const newDefinitionData = {
      ...(currentWord.definitionData || {
        targetChar: currentWord.word[0],
        options: [],
        correctIndex: 0
      }),
      simpleDefinition: editDefinition,
      exampleSentence: editExample
    };

    onUpdate(currentWord.id, { definitionData: newDefinitionData });
    setIsEditing(false);
  };

  const handleStartEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsEditing(true);
  };

  const handleCancelEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsEditing(false);
    // Reset to original values
    const defData = currentWord.definitionData;
    const definition = defData?.simpleDefinition 
      || (defData?.options && defData.correctIndex !== undefined ? defData.options[defData.correctIndex] : '')
      || "";
    const example = defData?.exampleSentence || "";
    setEditDefinition(definition);
    setEditExample(example);
  };

  const handleAiGenerate = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!currentWord || isGenerating) return;

    setIsGenerating(true);
    try {
      const res = await explainWord(currentWord.word);
      if (res) {
        if (isEditing) {
          setEditDefinition(res.simpleDefinition);
          setEditExample(res.exampleSentence);
        } else {
          const newDefinitionData = {
            ...(currentWord.definitionData || {
              targetChar: currentWord.word[0],
              options: [],
              correctIndex: 0
            }),
            simpleDefinition: res.simpleDefinition,
            exampleSentence: res.exampleSentence
          };
          onUpdate(currentWord.id, { definitionData: newDefinitionData });
        }
      }
    } catch (err) {
      alert("AI 生成失败，请稍后重试");
    } finally {
      setIsGenerating(false);
    }
  };

  // 提取显示数据 (用于非编辑模式)
  const displayData = useMemo(() => {
    if (!currentWord) return null;
    const defData = currentWord.definitionData;

    // 优先使用新字段 simpleDefinition，如果没有则尝试从选项中获取
    const definition = defData?.simpleDefinition 
      || (defData?.options ? defData.options[defData.correctIndex] : null)
      || "暂无释义 (点击编辑或 AI 补充)";

    const example = defData?.exampleSentence || "暂无例句 (点击编辑或 AI 补充)";

    return {
      word: currentWord.word,
      pinyin: currentWord.pinyin,
      definition,
      example
    };
  }, [currentWord]);

  if (filteredWords.length === 0) {
    return (
      <div className="min-h-screen bg-gray-100 flex flex-col p-6">
        <button onClick={onBack} className="text-gray-500 hover:text-gray-800 flex items-center font-bold mb-8 transition-colors self-start">
          <ArrowLeft className="w-5 h-5 mr-1" /> 返回
        </button>
        <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-400">
          <BookOpen className="w-16 h-16 mb-4 text-gray-300" />
          <p>当前筛选条件下没有可复习的生字词。</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center justify-center p-4 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-64 bg-primary/10 rounded-b-[3rem]"></div>

      {/* Header */}
      <div className="w-full max-w-lg flex items-center justify-between mb-8 z-10 relative">
        <button onClick={onBack} className="text-gray-600 hover:text-gray-900 bg-white/50 p-2 rounded-full backdrop-blur-sm transition-all shadow-sm">
          <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="flex items-center gap-2 bg-white/80 backdrop-blur-md px-3 py-1.5 rounded-full shadow-sm border border-white/50">
           <Filter className="w-4 h-4 text-primary" />
           <select 
             value={selectedDate} 
             onChange={handleDateChange}
             className="bg-transparent text-sm text-gray-700 font-bold focus:outline-none cursor-pointer"
           >
             <option value="">全部题库 ({words.filter(w => w.type === EntryType.WORD).length})</option>
             {availableDates.map(d => <option key={d} value={d}>{d}</option>)}
           </select>
        </div>

        <div className="text-gray-600 font-bold text-sm bg-white/50 px-3 py-1.5 rounded-full">
          {currentIndex + 1} / {filteredWords.length}
        </div>
      </div>

      {/* Main Content Area: Left Button + Card + Right Button */}
      <div className="relative w-full max-w-4xl flex items-center justify-center gap-4 md:gap-12 z-10">

        {/* Prev Button (Left) */}
        <button 
          onClick={handlePrev} 
          disabled={currentIndex === 0}
          className="hidden md:flex p-4 bg-white/80 rounded-full shadow-lg text-gray-700 hover:text-primary disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95 backdrop-blur-sm"
        >
          <ChevronLeft className="w-8 h-8" />
        </button>

        {/* Card Container */}
        <div className="w-full max-w-md aspect-[3/4] relative perspective-1000 group" onClick={() => !isEditing && setIsFlipped(!isFlipped)}>
          <div className={`w-full h-full relative transition-all duration-500 transform-style-3d cursor-pointer shadow-2xl rounded-3xl ${isFlipped ? 'rotate-y-180' : ''}`}>

            {/* Front */}
            <div className="absolute inset-0 bg-white rounded-3xl p-8 flex flex-col items-center justify-center backface-hidden border-2 border-white shadow-inner">
               <div className="flex-1 flex flex-col items-center justify-center gap-6">
                  <span className="text-3xl text-gray-500 font-medium font-sans tracking-widest">{displayData?.pinyin}</span>
                  <h2 className="text-7xl font-bold text-gray-800 font-serif mb-4">{displayData?.word}</h2>
                  <div className="w-16 h-1 bg-primary/20 rounded-full"></div>
               </div>
               <p className="text-gray-400 text-sm mt-auto animate-pulse">点击翻转查看释义</p>
            </div>

            {/* Back */}
            <div className="absolute inset-0 bg-gradient-to-br from-primary to-indigo-700 rounded-3xl p-6 md:p-8 flex flex-col items-center backface-hidden rotate-y-180 text-white shadow-xl">

               {/* Toolbar (Edit/Save/AI) */}
               <div className="w-full flex justify-end mb-2 gap-2">
