    if (isOverLimit) {
      alert(`为了保证分析质量，单次最多支持 ${MAX_BATCH_SIZE} 个词语，请分批录入。`);
      return;
    }

    const initialDrafts: DraftEntry[] = detectedWords.map(w => ({
      id: crypto.randomUUID(),
      word: w,
      analysis: null,
      enabledTypes: [...defaultTypes],
      status: 'pending',
      type: EntryType.WORD
    }));
